  1 │ /** ACP v1 stdio transport and runtime adapter for Nexus's existing sidecar protocol. */
  2 │ import * as fs from "node:fs";
  3 │ import * as path from "node:path";
  4 │ import type { HarnessConfig } from "./types.js";
  5 │ import { ApplicationCore } from "./core/app.js";
  6 │ import { formatSafeSidecarDiagnostic, SidecarServer } from "./sidecar.js";
  7 │ import { PROTOCOL_VERSION, type SidecarEvent } from "./protocol.js";
  8 │ import {
  9 │   ACP_CANCEL_REQUEST_METHOD, ACP_ERROR, ACP_MAX_INFLIGHT_REQUESTS, ACP_MAX_PENDING_PERMISSIONS_PER_SESSION,
 10 │   ACP_MAX_OVERSIZED_LINES, ACP_MAX_SESSIONS, ACP_PERMISSION_TIMEOUT_SECS, ACP_RECEIPT_STORE_SIZE, ACP_TOMBSTONE_COUNT,
 11 │   type AcpId, type AcpVerification,
 12 │ } from "./acp/types.js";
 13 │ import {
 14 │   BoundedLineReader, RequestCorrelator, encodeMessage, errorResponse, notification,
 15 │   oversizedLineError, parseMessage, request, resultResponse,
 16 │ } from "./acp/jsonrpc.js";
 17 │ import {
 18 │   approvalToPermissionRequest, assistantDeltaToUpdate, bindApprovalToToolCall, cancelledRequestError,
 19 │   fileDiffToUpdate, historyToReplay, initializeResult, loadSessionResult, newSessionResult, nexusReceipt,
 20 │   permissionReplyToCommand, promptResult, sessionUpdate, sidecarErrorToRpc, toolEndToUpdate, toolStartToUpdate,
 21 │   turnToStop, verificationFromTurn, verificationUpdate, verdictChunk,
 22 │ } from "./acp/mapping.js";
 23 │ import {
 24 │   canonicalCwd, validateCancel, validateCancelRequest, validateInitialize, validateLoadSession,
 25 │   validateNewSession, validatePrompt, validateReceiptGet,
 26 │ } from "./acp/validate.js";
 27 │ 
 28 │ type SidecarLike = { start(): void; handleLine(line: string): Promise<void> };
 29 │ type Session = {
 30 │   id: string; cwd: string; mcp: { count: number; names: string[] }; sidecar: SidecarLike;
 31 │   events: SidecarEvent[]; tools: SidecarEvent[]; pendingPrompt?: { rpcId: AcpId; commandId: string };
 32 │   pendingApproval?: { id: string; rpcId: number; toolCallId: string; timer: NodeJS.Timeout };
 33 │   pendingReceipt?: { commandId: string; resolve: (event: SidecarEvent | undefined) => void };
 34 │ };
 35 │ 
 36 │ export interface AcpStdioOptions {
 37 │   config: HarnessConfig;
 38 │   version: string;
 39 │   write?: (line: string) => void;
 40 │   createSidecar?: (config: HarnessConfig, resume: string | undefined, write: (line: string) => void) => SidecarLike;
 41 │   realpath?: (value: string) => string;
 42 │   isDirectory?: (value: string) => boolean;
 43 │ }
 44 │ 
 45 │ /** One ACP connection. Every session still executes through ApplicationCore and SidecarServer gates. */
 46 │ export class AcpStdioServer {
 47 │   private readonly write: (line: string) => void;
 48 │   private readonly reader = new BoundedLineReader();
 49 │   private readonly permissionRequests = new RequestCorrelator<{ sessionId: string; approvalId: string }>({ tombstones: ACP_TOMBSTONE_COUNT });
 50 │   private readonly sessions = new Map<string, Session>();
 51 │   private readonly receipts = new Map<string, ReturnType<typeof nexusReceipt>>();
 52 │   private readonly pending = new Map<string, AcpId>();
 53 │   private readonly loadingSessionIds = new Set<string>();
 54 │   private startingSessions = 0;
 55 │   private initialized = false;
 56 │   private closed = false;
 57 │ 
 58 │   constructor(private readonly options: AcpStdioOptions) {
 59 │     this.write = options.write ?? ((line) => process.stdout.write(line));
 60 │   }
 61 │ 
 62 │   /** Feed raw stdin bytes. Invalid/oversized lines are answered without retaining unbounded input. */
 63 │   push(chunk: Uint8Array): void {
 64 │     if (this.closed) return;
 65 │     for (const event of this.reader.push(chunk)) {
 66 │       if (this.closed) break;
 67 │       if (event.kind === "oversized") {
 68 │         this.write(encodeMessage(oversizedLineError()));
 69 │         if (this.reader.oversizedLines >= ACP_MAX_OVERSIZED_LINES) void this.close();
 70 │       }
 71 │       else void this.receive(event.text);
 72 │     }
 73 │   }
 74 │ 
 75 │   async close(): Promise<void> {
 76 │     this.closed = true;
 77 │     const shutdowns: Promise<void>[] = [];
 78 │     for (const session of this.sessions.values()) {
 79 │       if (session.pendingApproval) clearTimeout(session.pendingApproval.timer);
 80 │       shutdowns.push(session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })));
 81 │     }
 82 │     this.sessions.clear();
 83 │     this.pending.clear();
 84 │     await Promise.allSettled(shutdowns);
 85 │   }
 86 │ 
 87 │   private send(message: object): void {
 88 │     if (!this.closed) this.write(encodeMessage(message));
 89 │   }
 90 │ 
 91 │   private requestKey(id: AcpId): string { return `${typeof id}:${String(id)}`; }
 92 │ 
 93 │   private async receive(line: string): Promise<void> {
 94 │     const incoming = parseMessage(line);
 95 │     if (incoming.kind === "invalid") {
 96 │       if (incoming.respond) this.send(errorResponse(incoming.id, incoming.error));
 97 │       return;
 98 │     }
 99 │     if (incoming.kind === "response") {
100 │       const settled = this.permissionRequests.settle(incoming.id);
101 │       if (settled.state !== "matched") return;
102 │       const session = this.sessions.get(settled.context.sessionId);
103 │       if (!session?.pendingApproval || session.pendingApproval.rpcId !== incoming.id) return;
104 │       const pending = session.pendingApproval;
105 │       clearTimeout(pending.timer);
106 │       session.pendingApproval = undefined;
107 │       const command = permissionReplyToCommand(pending.id, incoming);
108 │       await this.sidecarCommand(session, command.type === "approve"
109 │         ? { type: "approve", id: command.id, always: false }
110 │         : { type: "deny", id: command.id });
111 │       return;
112 │     }
113 │     if (this.pending.size >= ACP_MAX_INFLIGHT_REQUESTS && incoming.kind === "request") {
114 │       this.send(errorResponse(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: "too many requests are in flight" }));
115 │       return;
116 │     }
117 │     if (incoming.kind === "request") this.pending.set(this.requestKey(incoming.id), incoming.id);
118 │     try {
119 │       await this.dispatch(incoming);
120 │     } catch (err) {
121 │       if (incoming.kind === "request") this.replyError(incoming.id, { code: ACP_ERROR.INTERNAL_ERROR, message: formatSafeSidecarDiagnostic([err]) });
122 │     } finally {
123 │       const promptStillRunning = incoming.kind === "request" && incoming.method === "session/prompt"
124 │         && [...this.sessions.values()].some((session) => session.pendingPrompt?.rpcId === incoming.id);
125 │       if (incoming.kind === "request" && !promptStillRunning) this.pending.delete(this.requestKey(incoming.id));
126 │     }
127 │   }
128 │ 
129 │   private replyError(id: AcpId, error: { code: number; message: string; data?: unknown }): void {
130 │     this.send(errorResponse(id, error as any));
131 │   }
132 │ 
133 │   private async dispatch(message: Exclude<ReturnType<typeof parseMessage>, { kind: "invalid" | "response" }>): Promise<void> {
134 │     if (message.kind === "request" && !this.initialized && message.method !== "initialize") {
135 │       this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize must be the first request" });
136 │       return;
137 │     }
138 │     if (message.method === "initialize" && message.kind === "request") {
139 │       if (this.initialized) { this.replyError(message.id, { code: ACP_ERROR.INVALID_REQUEST, message: "initialize was already completed" }); return; }
140 │       const parsed = validateInitialize(message.params);
141 │       if (!parsed.ok) { this.replyError(message.id, parsed.error); return; }
142 │       this.initialized = true;
143 │       this.send(resultResponse(message.id, initializeResult({ version: this.options.version, sidecarProtocol: PROTOCOL_VERSION })));
144 │       return;
145 │     }
146 │     if (!this.initialized) return;
147 │     if (message.method === "session/new" && message.kind === "request") return this.newSession(message.id, message.params);
148 │     if (message.method === "session/load" && message.kind === "request") return this.loadSession(message.id, message.params);
149 │     if (message.method === "session/prompt" && message.kind === "request") return this.prompt(message.id, message.params);
150 │     if (message.method === "session/cancel" && message.kind === "notification") {
151 │       const parsed = validateCancel(message.params);
152 │       if (parsed.ok) { const session = this.sessions.get(parsed.value.sessionId); if (session) await this.sidecarCommand(session, { type: "cancel" }); }
153 │       return;
154 │     }
155 │     if (message.method === ACP_CANCEL_REQUEST_METHOD && message.kind === "notification") {
156 │       const parsed = validateCancelRequest(message.params);
157 │       if (parsed.ok) {
158 │         const approval = this.permissionRequests.abandon(parsed.value.requestId as number);
159 │         if (approval) {
160 │           const session = this.sessions.get(approval.sessionId);
161 │           if (session?.pendingApproval?.rpcId === parsed.value.requestId) {
162 │             clearTimeout(session.pendingApproval.timer);
163 │             const approvalId = session.pendingApproval.id;
164 │             session.pendingApproval = undefined;
165 │             await this.sidecarCommand(session, { type: "deny", id: approvalId });
166 │           }
167 │         }
168 │         const id = this.pending.get(this.requestKey(parsed.value.requestId));
169 │         if (id !== undefined) {
170 │           for (const session of this.sessions.values()) if (session.pendingPrompt?.rpcId === id) {
171 │             session.pendingPrompt = undefined;
172 │             await this.sidecarCommand(session, { type: "cancel" });
173 │             this.send(cancelledRequestError(id));
174 │             this.pending.delete(this.requestKey(id));
175 │           }
176 │         }
177 │       }
178 │       return;
179 │     }
180 │     if (message.method === "_nexus/receipt/get" && message.kind === "request") return this.getReceipt(message.id, message.params);
181 │     if (message.kind === "request") this.replyError(message.id, { code: ACP_ERROR.METHOD_NOT_FOUND, message: `method not found: ${message.method}` });
182 │   }
183 │ 
184 │   private canonical(cwd: string): string | undefined {
185 │     const result = canonicalCwd(cwd, {
186 │       realpath: this.options.realpath ?? ((value) => fs.realpathSync(value)),
187 │       isDirectory: this.options.isDirectory ?? ((value) => fs.statSync(value).isDirectory()),
188 │     });
189 │     return result.ok ? result.value : undefined;
190 │   }
191 │ 
192 │   private async startSession(cwd: string, mcp: { count: number; names: string[] }, resume?: string): Promise<Session | undefined> {
193 │     const config = { ...this.options.config, workspace: cwd, surface: "tui" as const };
194 │     const events: SidecarEvent[] = [];
195 │     const early: string[] = [];
196 │     let session: Session;
197 │     const sink = (line: string) => session ? this.onSidecarLine(session, line) : early.push(line);
198 │     const sidecar = this.options.createSidecar?.(config, resume, sink)
199 │       ?? new SidecarServer({ app: new ApplicationCore(config), resume, write: sink });
200 │     session = { id: "", cwd, mcp, sidecar, events, tools: [] };
201 │     try {
202 │       sidecar.start();
203 │     } catch (err) {
204 │       await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
205 │       throw err;
206 │     }
207 │     for (const line of early) this.onSidecarLine(session, line);
208 │     await new Promise((resolve) => setImmediate(resolve));
209 │     if (this.closed) {
210 │       await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
211 │       return undefined;
212 │     }
213 │     const state = events.find((event) => event.type === "session.state") as Extract<SidecarEvent, { type: "session.state" }> | undefined;
214 │     if (!state?.session || (resume !== undefined && state.session !== resume)) {
215 │       await sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" }));
216 │       return undefined;
217 │     }
218 │     session.id = state.session;
219 │     return session;
220 │   }
221 │ 
222 │   private async newSession(id: AcpId, params: unknown): Promise<void> {
223 │     const parsed = validateNewSession(params);
224 │     if (!parsed.ok) { this.replyError(id, parsed.error); return; }
225 │     const cwd = this.canonical(parsed.value.cwd);
226 │     if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
227 │     if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
228 │     this.startingSessions++;
229 │     try {
230 │       const session = await this.startSession(cwd, parsed.value.mcpServers);
231 │       if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "sidecar did not establish a session" }); return; }
232 │       if (this.sessions.has(session.id)) { await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })); this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the sidecar generated a duplicate session id" }); return; }
233 │       this.sessions.set(session.id, session);
234 │       const state = session.events.find((event) => event.type === "session.state") as any;
235 │       this.send(resultResponse(id, newSessionResult(state, session.mcp) ?? { sessionId: session.id }));
236 │     } finally {
237 │       this.startingSessions--;
238 │     }
239 │   }
240 │ 
241 │   private async loadSession(id: AcpId, params: unknown): Promise<void> {
242 │     const parsed = validateLoadSession(params);
243 │     if (!parsed.ok) { this.replyError(id, parsed.error); return; }
244 │     const cwd = this.canonical(parsed.value.cwd);
245 │     if (!cwd) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "cwd does not exist or is not a readable directory" }); return; }
246 │     if (this.sessions.has(parsed.value.sessionId) || this.loadingSessionIds.has(parsed.value.sessionId)) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "session is already active on this connection" }); return; }
247 │     if (this.sessions.size + this.startingSessions >= ACP_MAX_SESSIONS) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "the connection already has the maximum number of sessions" }); return; }
248 │     this.startingSessions++;
249 │     this.loadingSessionIds.add(parsed.value.sessionId);
250 │     try {
251 │       const session = await this.startSession(cwd, parsed.value.mcpServers, parsed.value.sessionId);
252 │       if (!session) { if (!this.closed) this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "session could not be loaded" }); return; }
253 │       this.sessions.set(session.id, session);
254 │       const history = session.events.find((event) => event.type === "history") as Extract<SidecarEvent, { type: "history" }> | undefined;
255 │       if (history) for (const update of historyToReplay(history).updates) this.send(sessionUpdate(session.id, update));
256 │       const state = session.events.find((event) => event.type === "session.state") as any;
257 │       const extent = history ? historyToReplay(history).extent : { sent: 0, total: 0 };
258 │       this.send(resultResponse(id, loadSessionResult(state, session.mcp, extent)));
259 │     } finally {
260 │       this.startingSessions--;
261 │       this.loadingSessionIds.delete(parsed.value.sessionId);
262 │     }
263 │   }
264 │ 
265 │   private async prompt(id: AcpId, params: unknown): Promise<void> {
266 │     const rawSessionId = (params && typeof params === "object") ? (params as any).sessionId : undefined;
267 │     const session = typeof rawSessionId === "string" ? this.sessions.get(rawSessionId) : undefined;
268 │     if (!session) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "sessionId is not active on this connection" }); return; }
269 │     const parsed = validatePrompt(params, { workspace: session.cwd, fs: { realpath: (value) => fs.realpathSync(value), isDirectory: (value) => fs.statSync(value).isDirectory() } });
270 │     if (!parsed.ok) { this.replyError(id, parsed.error); return; }
271 │     if (session.pendingPrompt) { this.replyError(id, { code: ACP_ERROR.INTERNAL_ERROR, message: "this session already has a prompt in progress" }); return; }
272 │     const commandId = `acp-${String(id).slice(0, 180)}`;
273 │     session.pendingPrompt = { rpcId: id, commandId };
274 │     await this.sidecarCommand(session, { type: "prompt.submit", id: commandId, text: parsed.value.text });
275 │   }
276 │ 
277 │   private async getReceipt(id: AcpId, params: unknown): Promise<void> {
278 │     const parsed = validateReceiptGet(params);
279 │     if (!parsed.ok) { this.replyError(id, parsed.error); return; }
280 │     const receipt = parsed.value.receiptId ? this.receipts.get(parsed.value.receiptId) : [...this.receipts.values()].reverse().find((value) => value.session_id === parsed.value.sessionId);
281 │     if (!receipt || receipt.session_id !== parsed.value.sessionId) { this.replyError(id, { code: ACP_ERROR.INVALID_PARAMS, message: "receipt is not available on this connection" }); return; }
282 │     this.send(resultResponse(id, receipt));
283 │   }
284 │ 
285 │   private async sidecarCommand(session: Session, command: Record<string, unknown>): Promise<void> {
286 │     await session.sidecar.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, ...command }));
287 │   }
288 │ 
289 │   private onSidecarLine(session: Session | undefined, line: string): void {
290 │     if (!session) return;
291 │     let event: SidecarEvent;
292 │     try { event = JSON.parse(line); } catch { return; }
293 │     session.events.push(event);
294 │     if (session.events.length > 2_000) session.events.shift();
295 │     if (event.type === "tool.start") {
296 │       session.tools.push(event);
297 │       this.send(sessionUpdate(session.id, toolStartToUpdate(event as any)));
298 │     } else if (event.type === "assistant.delta") this.send(sessionUpdate(session.id, assistantDeltaToUpdate(event as any)));
299 │     else if (event.type === "file.diff") this.send(sessionUpdate(session.id, fileDiffToUpdate(event as any, session.cwd)));
300 │     else if (event.type === "tool.end") this.send(sessionUpdate(session.id, toolEndToUpdate(event as any)));
301 │     else if (event.type === "approval.request") this.permission(session, event as any);
302 │     else if (event.type === "turn.result") void this.finishPrompt(session, event as any);
303 │     else if (event.type === "error" && session.pendingPrompt && event.id === session.pendingPrompt.commandId) {
304 │       this.replyError(session.pendingPrompt.rpcId, sidecarErrorToRpc(event as any));
305 │       this.pending.delete(this.requestKey(session.pendingPrompt.rpcId));
306 │       session.pendingPrompt = undefined;
307 │     }
308 │     if (session.pendingReceipt && event.type === "receipt" && event.id === session.pendingReceipt.commandId) {
309 │       const pending = session.pendingReceipt; session.pendingReceipt = undefined; pending.resolve(event);
310 │     }
311 │     if (event.type === "session.state" && !session.id && event.session) session.id = event.session;
312 │   }
313 │ 
314 │   private permission(session: Session, event: Extract<SidecarEvent, { type: "approval.request" }>): void {
315 │     if (session.pendingApproval || ACP_MAX_PENDING_PERMISSIONS_PER_SESSION !== 1) {
316 │       void this.sidecarCommand(session, { type: "deny", id: event.id }); return;
317 │     }
318 │     const toolCallId = bindApprovalToToolCall(event as any, session.tools as any);
319 │     const rpcId = this.permissionRequests.open({ sessionId: session.id, approvalId: event.id });
320 │     const timer = setTimeout(() => {
321 │       this.permissionRequests.abandon(rpcId);
322 │       if (session.pendingApproval?.rpcId === rpcId) session.pendingApproval = undefined;
323 │       void this.sidecarCommand(session, { type: "deny", id: event.id });
324 │     }, ACP_PERMISSION_TIMEOUT_SECS * 1000);
325 │     timer.unref?.();
326 │     session.pendingApproval = { id: event.id, rpcId, toolCallId, timer };
327 │     this.send(approvalToPermissionRequest(event as any, { rpcId, sessionId: session.id, toolCallId, workspace: session.cwd }));
328 │   }
329 │ 
330 │   private async finishPrompt(session: Session, event: Extract<SidecarEvent, { type: "turn.result" }>): Promise<void> {
331 │     const pending = session.pendingPrompt;
332 │     if (!pending) return;
333 │     if (session.pendingApproval) {
334 │       clearTimeout(session.pendingApproval.timer); this.permissionRequests.abandon(session.pendingApproval.rpcId); session.pendingApproval = undefined;
335 │     }
336 │     const resultId = `acp-receipt-${pending.commandId}`;
337 │     let sections: any[] = [];
338 │     try {
339 │       const detail = await new Promise<SidecarEvent | undefined>((resolve) => {
340 │         const timer = setTimeout(() => { if (session.pendingReceipt?.commandId === resultId) session.pendingReceipt = undefined; resolve(undefined); }, 2_000);
341 │         session.pendingReceipt = { commandId: resultId, resolve: (value) => { clearTimeout(timer); resolve(value); } };
342 │         void this.sidecarCommand(session, { type: "receipt", id: resultId });
343 │       });
344 │       if (detail?.type === "receipt") sections = detail.sections;
345 │     } catch { /* A missing receipt is represented as missing evidence, never as a passed verifier. */ }
346 │     const turnId = event.turn_id ?? null;
347 │     const verification: AcpVerification = verificationFromTurn({ sessionId: session.id, turnId, turn: event.turn, sections });
348 │     const receipt = nexusReceipt(session.id, verification, sections);
349 │     this.receipts.set(receipt.receipt_id, receipt);
350 │     while (this.receipts.size > ACP_RECEIPT_STORE_SIZE) this.receipts.delete(this.receipts.keys().next().value as string);
351 │     const mapped = turnToStop(event.turn);
352 │     this.send(sessionUpdate(session.id, verificationUpdate(verification) as any));
353 │     this.send(sessionUpdate(session.id, verdictChunk(event.heading, event.line)));
354 │     if ("error" in mapped) this.replyError(pending.rpcId, mapped.error);
355 │     else this.send(resultResponse(pending.rpcId, promptResult(mapped.stopReason, verification)));
356 │     this.pending.delete(this.requestKey(pending.rpcId));
357 │     session.pendingPrompt = undefined;
358 │     session.tools = [];
359 │   }
360 │ }
361 │ 
362 │ /** Attach the adapter to process stdio. Stdout is reserved for JSON-RPC messages. */
363 │ export function runAcpStdio(options: AcpStdioOptions): AcpStdioServer {
364 │   const protocolWrite = process.stdout.write.bind(process.stdout);
365 │   // ACP owns stdout for the lifetime of this command; incidental logs must never corrupt the wire stream.
366 │   (process.stdout as any).write = (_chunk: unknown, encoding?: unknown, callback?: unknown): boolean => {
367 │     const done = typeof encoding === "function" ? encoding : callback;
368 │     if (typeof done === "function") queueMicrotask(done as () => void);
369 │     return true;
370 │   };
371 │   const server = new AcpStdioServer({ ...options, write: options.write ?? ((line) => protocolWrite(line)) });
372 │   process.stdin.on("data", (chunk: Buffer) => server.push(chunk));
373 │   process.stdin.once("end", () => { void server.close(); });
374 │   process.once("SIGINT", () => { void server.close().then(() => { process.exitCode = 130; }); });
375 │   process.once("SIGTERM", () => { void server.close().then(() => { process.exitCode = 143; }); });
376 │   return server;
377 │ }
