357	/**
358	 * The diff of a file change as a `tool_call_update`. With the tool call's detail record (`tool.detail`) the full diff
359	 * is used; without it, the bounded preview the `file.diff` event carries. `_meta["nexus/diff"]` says which it was.
360	 */
361	export function fileDiffToUpdate(event: Event<"file.diff">, workspace: string, detail?: Event<"tool.detail">): AcpToolCallUpdate {
362	  const full = detail?.diff;
363	  const { blocks, truncated } = unifiedDiffToBlocks(full ?? event.preview, workspace, event.path);
364	  const cut = truncated || (full === undefined ? event.truncated : (detail?.diff_chars ?? full.length) > full.length);
365	  return {
366	    sessionUpdate: "tool_call_update",
367	    toolCallId: toolCallId(event),
368	    status: "in_progress",
369	    ...(blocks.length ? { content: blocks } : {}),
370	    _meta: { [ACP_META_DIFF]: { kind: event.kind, added: event.added, removed: event.removed, truncated: cut } },
371	  };
