374	function canonicalJson(value: unknown): string {
375	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
376	  if (value && typeof value === "object") {
377	    const object = value as Record<string, unknown>;
378	    const keys = Object.keys(object).filter((key) => object[key] !== undefined).sort();
379	    return `{${keys.map((key) => `${JSON.stringify(key)}:${canonicalJson(object[key])}`).join(",")}}`;
380	  }
381	  return JSON.stringify(value ?? null);
382	}
