384	/** SHA-256 (hex) of the canonical `{tool, subject, preview, review}` of an approval: what the operator was shown. */
385	export function approvalDigest(event: Event<"approval.request">): string {
386	  const { tool, subject, preview, review } = event;
387	  return createHash("sha256").update(canonicalJson({ tool, subject, preview, review })).digest("hex");
