426	/**
427	 * `approval.request` as a `session/request_permission` request with exactly the two options allow-once and reject.
428	 * `rpcId` comes from the adapter's `RequestCorrelator`, `toolCallId` from `bindApprovalToToolCall`.
429	 */
430	export function approvalToPermissionRequest(event: Event<"approval.request">, binding: { rpcId: number; sessionId: string; toolCallId: string; workspace: string }): AcpPermissionRequest {
431	  return request(binding.rpcId, "session/request_permission", {
432	    sessionId: binding.sessionId,
433	    toolCall: {
434	      toolCallId: binding.toolCallId,
435	      title: toolTitle(event.tool, event.subject),
436	      kind: toolKind(event.tool),
437	      status: "pending",
438	      content: reviewContent(event, binding.workspace),
439	      rawInput: { tool: event.tool, subject: event.subject },
440	      _meta: { [ACP_META_APPROVAL_DIGEST]: approvalDigest(event) },
441	    },
442	    options: ACP_PERMISSION_OPTIONS.map((option) => ({ ...option })),
443	  });
444	}
