446	/** The only two commands a permission reply can become. `always` has the literal type `false`: no caller can widen it. */
447	export type ApprovalCommand = { type: "approve"; id: string; always: false } | { type: "deny"; id: string };
448	
449	/**
450	 * A client's reply to a permission request, as the sidecar command for the approval it answers. THE ONE DECISION POINT:
451	 * `approve` (once, never "always") only for a well-formed `selected` outcome whose option id is the allow-once id Nexus
452	 * offered. Everything else is `deny`: reject, cancelled, an option id that was not offered (`allow_always` included), a
453	 * JSON-RPC error, a malformed or missing result.
454	 *
455	 * The caller must have matched the reply to an open request first (`RequestCorrelator.settle` returned `matched`); a
456	 * stale or unknown reply is never passed here, so it produces no command at all.
457	 */
458	export function permissionReplyToCommand(approvalId: string, reply: { result: unknown } | { error: unknown }): ApprovalCommand {
459	  const deny: ApprovalCommand = { type: "deny", id: approvalId };
460	  if (!Object.hasOwn(reply, "result") || Object.hasOwn(reply, "error")) return deny;
461	  const parsed = validatePermissionResult((reply as { result: unknown }).result);
462	  if (!parsed.ok || parsed.value.outcome !== "selected") return deny;
463	  if (parsed.value.optionId !== ACP_ALLOW_ONCE_OPTION_ID) return deny;
464	  return { type: "approve", id: approvalId, always: false };
465	}
