2	     2	 * Newline-delimited JSON-RPC 2.0 for the ACP adapter: a bounded line reader, classification of one line, encoding, and
3	     3	 * the correlator of agent-to-client requests. "Messages are delimited by newlines, and MUST NOT contain embedded
4	     4	 * newlines"; UTF-8 (published specification, transports).
5	     5	 *
6	     6	 * Pure: it takes chunks and returns results. No process, no stdio, no timer.
7	     7	 */
8	     8	import { randomInt } from "node:crypto";
9	     9	import {
10	    10	  ACP_ERROR,
11	    11	  ACP_MAX_JSON_DEPTH,
12	    12	  ACP_MAX_LINE_BYTES,
13	    13	  ACP_MAX_METHOD_CHARS,
14	    14	  ACP_MAX_REQUEST_ID_CHARS,
15	    15	  ACP_NV_BATCH_CODE,
16	    16	  ACP_TOMBSTONE_COUNT,
17	    17	  JSONRPC_VERSION,
18	    18	} from "./types.js";
19	    19	import type { AcpClientError, AcpError, AcpErrorCode, AcpErrorData, AcpErrorResponse, AcpId } from "./types.js";
20	    20	
21	    21	const NEWLINE = 0x0a;
22	    22	
23	    23	export type LineEvent =
24	    24	  /** One complete line, decoded, without its terminator. Blank lines are never reported. */
25	    25	  | { kind: "line"; text: string }
26	    26	  /** A line longer than the cap. Reported once, when the cap is passed; the rest of the line is discarded unread. */
27	    27	  | { kind: "oversized" };
28	    28	
29	    29	/**
30	    30	 * Splits a byte stream into lines without ever holding more than `maxBytes` of one line: when a line passes the cap,
31	    31	 * what was buffered is dropped, `oversized` is reported once, and bytes are discarded up to the next newline. A line of
32	    32	 * exactly `maxBytes` bytes (terminator not counted) is accepted. `\r\n` is accepted; blank lines are ignored.
33	    33	 */
34	    34	export class BoundedLineReader {
35	    35	  private parts: Buffer[] = [];
36	    36	  private held = 0;
37	    37	  private discarding = false;
38	    38	  private oversized = 0;
39	    39	
40	    40	  constructor(private readonly maxBytes: number = ACP_MAX_LINE_BYTES) {}
41	    41	
42	    42	  /** Bytes of the unfinished line held now: never more than the cap, and 0 while an oversized line is being discarded. */
43	    43	  get bufferedBytes(): number {
44	    44	    return this.held;
45	    45	  }
46	    46	
47	    47	  /** Lines over the cap seen so far. */
48	    48	  get oversizedLines(): number {
49	    49	    return this.oversized;
50	    50	  }
51	    51	
52	    52	  push(chunk: Uint8Array): LineEvent[] {
53	    53	    const events: LineEvent[] = [];
54	    54	    let at = 0;
55	    55	    while (at < chunk.length) {
56	    56	      const newline = chunk.indexOf(NEWLINE, at);
57	    57	      const end = newline < 0 ? chunk.length : newline;
58	    58	      const length = end - at;
59	    59	      if (!this.discarding) {
60	    60	        if (this.held + length > this.maxBytes) {
61	    61	          this.drop();
62	    62	          this.discarding = true;
63	    63	          this.oversized++;
64	    64	          events.push({ kind: "oversized" });
65	    65	        } else if (length > 0) {
66	    66	          // Copied: the caller may reuse its chunk.
67	    67	          this.parts.push(Buffer.from(chunk.subarray(at, end)));
68	    68	          this.held += length;
69	    69	        }
70	    70	      }
71	    71	      if (newline < 0) break;
72	    72	      if (this.discarding) this.discarding = false;
73	    73	      else this.finish(events);
74	    74	      at = newline + 1;
75	    75	    }
76	    76	    return events;
