482	   482	  return ok({ cwd: cwd.value, mcpServers: servers.value });
483	   483	}
484	   484	
485	   485	export interface LoadSessionInput extends NewSessionInput {
486	   486	  sessionId: string;
487	   487	}
488	   488	
489	   489	export function validateLoadSession(params: unknown): Validated<LoadSessionInput> {
490	   490	  const p = record(params);
491	   491	  if (!p) return fail("params", "session/load requires a params object");
492	   492	  const sessionId = validateSessionId(member(p, "sessionId"));
493	   493	  if (!sessionId.ok) return sessionId;
494	   494	  const rest = validateNewSession(p);
495	   495	  if (!rest.ok) return rest;
496	   496	  return ok({ sessionId: sessionId.value, ...rest.value });
497	   497	}
498	   498	
499	   499	/**
500	   500	 * A `resource_link` as one line of prompt text. A `file://` URI whose real path lies inside the workspace becomes
501	   501	 * `Referenced file: <path relative to the workspace>`; anything else becomes `Reference: <the URI, on one line>`.
502	   502	 * Nothing is read or fetched: the agent reaches the file, if it wants it, through its own gated tools.
503	   503	 * `workspace` must already be canonical.
504	   504	 */
505	   505	export function resourceLinkLine(uri: string, workspace: string, fs: AcpFs): string {
506	   506	  if (/^file:\/\//i.test(uri)) {
507	   507	    try {
508	   508	      const real = fs.realpath(fileURLToPath(new URL(uri)));
509	   509	      const relative = path.relative(workspace, real);
510	   510	      const inside = relative !== "" && !path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`);
511	   511	      if (inside && !CONTROL.test(relative)) return `Referenced file: ${relative}`;
512	   512	    } catch {
513	   513	      // Not a path that exists here: it stays an opaque reference.
514	   514	    }
515	   515	  }
516	   516	  return `Reference: ${singleLine(uri, ACP_MAX_URI_CHARS)}`;
517	   517	}
518	   518	
519	   519	export interface PromptInput {
520	   520	  sessionId: string;
521	   521	  /** The prompt as the sidecar receives it: text blocks and reference lines, one per line group, in order. */
522	   522	  text: string;
523	   523	}
524	   524	
525	   525	const REFUSED_BLOCKS: Record<string, string> = {
526	   526	  image: "image content is not supported",
527	   527	  audio: "audio content is not supported",
528	   528	  resource: "embedded resources are not supported; send a resource_link",
529	   529	};
530	   530	
531	   531	/**
532	   532	 * `session/prompt`: content blocks to prompt text. `text` is taken as it is; `resource_link` becomes a reference line
533	   533	 * (see `resourceLinkLine`); `image`, `audio` and `resource` are refused, naming the block.
534	   534	 */
535	   535	export function validatePrompt(params: unknown, context: { workspace: string; fs: AcpFs }): Validated<PromptInput> {
536	   536	  const p = record(params);
537	   537	  if (!p) return fail("params", "session/prompt requires a params object");
538	   538	  const sessionId = validateSessionId(member(p, "sessionId"));
539	   539	  if (!sessionId.ok) return sessionId;
540	   540	  const blocks = member(p, "prompt");
541	   541	  if (!Array.isArray(blocks) || blocks.length === 0) return fail("prompt", "prompt must be a non-empty array of content blocks");
542	   542	  if (blocks.length > ACP_MAX_PROMPT_BLOCKS) return fail("prompt", `prompt has more than ${ACP_MAX_PROMPT_BLOCKS} content blocks`);
543	   543	  const parts: string[] = [];
544	   544	  let total = 0;
545	   545	  for (let i = 0; i < blocks.length; i++) {
546	   546	    const field = `prompt[${i}]`;
547	   547	    const block = record(blocks[i]);
548	   548	    if (!block) return fail(field, `prompt block ${i} must be an object`);
549	   549	    const type = member(block, "type");
550	   550	    let part: string;
551	   551	    if (type === "text") {
552	   552	      const text = member(block, "text");
553	   553	      if (typeof text !== "string") return fail(`${field}.text`, `prompt block ${i}: text must be a string`);
554	   554	      if (text.length > ACP_MAX_TEXT_BLOCK_CHARS) return fail(`${field}.text`, `prompt block ${i}: text is longer than ${ACP_MAX_TEXT_BLOCK_CHARS} characters`);
555	   555	      if (text.includes("\0")) return fail(`${field}.text`, `prompt block ${i}: text must not contain a NUL`);
556	   556	      part = text;
557	   557	    } else if (type === "resource_link") {
558	   558	      const uri = member(block, "uri");
559	   559	      if (typeof uri !== "string" || !uri) return fail(`${field}.uri`, `prompt block ${i}: uri must be a non-empty string`);
560	   560	      if (uri.length > ACP_MAX_URI_CHARS) return fail(`${field}.uri`, `prompt block ${i}: uri is longer than ${ACP_MAX_URI_CHARS} characters`);
561	   561	      part = resourceLinkLine(uri, context.workspace, context.fs);
562	   562	    } else if (typeof type === "string" && Object.hasOwn(REFUSED_BLOCKS, type)) {
563	   563	      return fail(field, `prompt block ${i}: ${REFUSED_BLOCKS[type]}`);
564	   564	    } else {
565	   565	      return fail(`${field}.type`, `prompt block ${i}: unknown content type`);
566	   566	    }
567	   567	    total += part.length + (parts.length ? 1 : 0);
568	   568	    if (total > ACP_MAX_PROMPT_CHARS) return fail("prompt", `the prompt is longer than ${ACP_MAX_PROMPT_CHARS} characters`);
569	   569	    parts.push(part);
570	   570	  }
571	   571	  const text = parts.join("\n");
572	   572	  if (!text.trim()) return fail("prompt", "the prompt has no text");
573	   573	  return ok({ sessionId: sessionId.value, text });
574	   574	}
575	   575	
576	   576	export function validateCancel(params: unknown): Validated<{ sessionId: string }> {
577	   577	  const p = record(params);
578	   578	  if (!p) return fail("params", "session/cancel requires a params object");
579	   579	  const sessionId = validateSessionId(member(p, "sessionId"));
580	   580	  return sessionId.ok ? ok({ sessionId: sessionId.value }) : sessionId;
581	   581	}
582	   582	
583	   583	/** `$/cancel_request`: the id of the request to cancel. */
584	   584	export function validateCancelRequest(params: unknown): Validated<{ requestId: AcpId }> {
585	   585	  const p = record(params);
586	   586	  if (!p) return fail("params", "$/cancel_request requires a params object");
587	   587	  const requestId = member(p, "requestId");
588	   588	  if (!isRequestId(requestId)) return fail("requestId", "requestId must be a string or an integer");
589	   589	  return ok({ requestId });
590	   590	}
591	   591	
592	   592	export function validateReceiptGet(params: unknown): Validated<{ sessionId: string; receiptId?: string }> {
593	   593	  const p = record(params);
594	   594	  if (!p) return fail("params", "the receipt request requires a params object");
595	   595	  const sessionId = validateSessionId(member(p, "sessionId"));
596	   596	  if (!sessionId.ok) return sessionId;
597	   597	  if (!present(p, "receiptId")) return ok({ sessionId: sessionId.value });
598	   598	  const receiptId = p.receiptId;
599	   599	  if (typeof receiptId !== "string" || !receiptId || receiptId.length > ACP_MAX_RECEIPT_ID_CHARS || CONTROL.test(receiptId)) {
600	   600	    return fail("receiptId", `receiptId must be a non-empty string of at most ${ACP_MAX_RECEIPT_ID_CHARS} characters`);
601	   601	  }
602	   602	  return ok({ sessionId: sessionId.value, receiptId });
603	   603	}
604	   604	
605	   605	/**
606	   606	 * The shape of the `result` of a reply to `session/request_permission`: `{outcome: {outcome: "selected", optionId}}`
607	   607	 * or `{outcome: {outcome: "cancelled"}}`. Shape only: which option id approves is decided in one place,
608	   608	 * `permissionReplyToCommand` in mapping.ts. There is nobody to send this error to: the caller denies.
609	   609	 */
610	   610	export function validatePermissionResult(result: unknown): Validated<AcpPermissionOutcome> {
611	   611	  const r = record(result);
612	   612	  if (!r) return fail("result", "a permission result must be an object");
613	   613	  const outcome = record(member(r, "outcome"));
614	   614	  if (!outcome) return fail("outcome", "a permission result needs an outcome object");
615	   615	  const kind = member(outcome, "outcome");
616	   616	  if (kind === "cancelled") return ok({ outcome: "cancelled" });
617	   617	  if (kind !== "selected") return fail("outcome.outcome", "the outcome must be selected or cancelled");
618	   618	  const optionId = member(outcome, "optionId");
619	   619	  if (typeof optionId !== "string") return fail("outcome.optionId", "a selected outcome needs a string optionId");
620	   620	  return ok({ outcome: "selected", optionId });
621	   621	}
