  1	/**
  2	 * Newline-delimited JSON-RPC 2.0 for the ACP adapter: a bounded line reader, classification of one line, encoding, and
  3	 * the correlator of agent-to-client requests. "Messages are delimited by newlines, and MUST NOT contain embedded
  4	 * newlines"; UTF-8 (published specification, transports).
  5	 *
  6	 * Pure: it takes chunks and returns results. No process, no stdio, no timer.
  7	 */
  8	import { randomInt } from "node:crypto";
  9	import {
 10	  ACP_ERROR,
 11	  ACP_MAX_JSON_DEPTH,
 12	  ACP_MAX_LINE_BYTES,
 13	  ACP_MAX_METHOD_CHARS,
 14	  ACP_MAX_REQUEST_ID_CHARS,
 15	  ACP_NV_BATCH_CODE,
 16	  ACP_TOMBSTONE_COUNT,
 17	  JSONRPC_VERSION,
 18	} from "./types.js";
 19	import type { AcpClientError, AcpError, AcpErrorCode, AcpErrorData, AcpErrorResponse, AcpId } from "./types.js";
 20	
 21	const NEWLINE = 0x0a;
 22	
 23	export type LineEvent =
 24	  /** One complete line, decoded, without its terminator. Blank lines are never reported. */
 25	  | { kind: "line"; text: string }
 26	  /** A line longer than the cap. Reported once, when the cap is passed; the rest of the line is discarded unread. */
 27	  | { kind: "oversized" };
 28	
 29	/**
 30	 * Splits a byte stream into lines without ever holding more than `maxBytes` of one line: when a line passes the cap,
 31	 * what was buffered is dropped, `oversized` is reported once, and bytes are discarded up to the next newline. A line of
 32	 * exactly `maxBytes` bytes (terminator not counted) is accepted. `\r\n` is accepted; blank lines are ignored.
 33	 */
 34	export class BoundedLineReader {
 35	  private parts: Buffer[] = [];
 36	  private held = 0;
 37	  private discarding = false;
 38	  private oversized = 0;
 39	
 40	  constructor(private readonly maxBytes: number = ACP_MAX_LINE_BYTES) {}
 41	
 42	  /** Bytes of the unfinished line held now: never more than the cap, and 0 while an oversized line is being discarded. */
 43	  get bufferedBytes(): number {
 44	    return this.held;
 45	  }
 46	
 47	  /** Lines over the cap seen so far. */
 48	  get oversizedLines(): number {
 49	    return this.oversized;
 50	  }
 51	
 52	  push(chunk: Uint8Array): LineEvent[] {
 53	    const events: LineEvent[] = [];
 54	    let at = 0;
 55	    while (at < chunk.length) {
 56	      const newline = chunk.indexOf(NEWLINE, at);
 57	      const end = newline < 0 ? chunk.length : newline;
 58	      const length = end - at;
 59	      if (!this.discarding) {
 60	        if (this.held + length > this.maxBytes) {
 61	          this.drop();
 62	          this.discarding = true;
 63	          this.oversized++;
 64	          events.push({ kind: "oversized" });
 65	        } else if (length > 0) {
 66	          // Copied: the caller may reuse its chunk.
 67	          this.parts.push(Buffer.from(chunk.subarray(at, end)));
 68	          this.held += length;
 69	        }
 70	      }
 71	      if (newline < 0) break;
 72	      if (this.discarding) this.discarding = false;
 73	      else this.finish(events);
 74	      at = newline + 1;
 75	    }
 76	    return events;
 77	  }
 78	
 79	  /** The stream ended: an unterminated last line is still a line. */
 80	  end(): LineEvent[] {
 81	    const events: LineEvent[] = [];
 82	    if (!this.discarding) this.finish(events);
 83	    this.discarding = false;
 84	    return events;
 85	  }
 86	
 87	  private drop(): void {
 88	    this.parts = [];
 89	    this.held = 0;
 90	  }
 91	
 92	  private finish(events: LineEvent[]): void {
 93	    if (this.held === 0) return;
 94	    const text = (this.parts.length === 1 ? this.parts[0] : Buffer.concat(this.parts, this.held)).toString("utf8");
 95	    this.drop();
 96	    const line = text.endsWith("\r") ? text.slice(0, -1) : text;
 97	    if (line.trim()) events.push({ kind: "line", text: line });
 98	  }
 99	}
100	
101	/**
102	 * Whether `text` nests arrays and objects deeper than `max`, decided before parsing so a depth bomb never reaches
103	 * `JSON.parse`. Brackets inside strings are not counted.
104	 */
105	export function exceedsDepth(text: string, max: number = ACP_MAX_JSON_DEPTH): boolean {
106	  let depth = 0;
107	  let inString = false;
108	  for (let i = 0; i < text.length; i++) {
109	    const code = text.charCodeAt(i);
110	    if (inString) {
111	      if (code === 0x5c) i++; // a backslash escapes the next character
112	      else if (code === 0x22) inString = false;
113	      continue;
114	    }
115	    if (code === 0x22) inString = true;
116	    else if (code === 0x5b || code === 0x7b) {
117	      if (++depth > max) return true;
118	    } else if (code === 0x5d || code === 0x7d) depth--;
119	  }
120	  return false;
121	}
122	
123	export type Incoming =
124	  | { kind: "request"; id: AcpId; method: string; params: unknown }
125	  | { kind: "notification"; method: string; params: unknown }
126	  /** A reply to an agent request: exactly one of `result` and `error` is present. */
127	  | { kind: "response"; id: AcpId; result: unknown; error?: undefined }
128	  | { kind: "response"; id: AcpId; result?: undefined; error: AcpClientError }
129	  /**
130	   * Not a message Nexus can act on. `respond`: whether to answer with `error` (false for something shaped like a reply,
131	   * which is logged and dropped: answering a reply with an error invites a loop).
132	   */
133	  | { kind: "invalid"; id: AcpId | null; error: AcpError; respond: boolean };
134	
135	function own(object: object, key: string): boolean {
136	  return Object.hasOwn(object, key);
137	}
138	
139	/** A request id Nexus accepts: a string of bounded length, or an integer. Null, a fraction and anything else are refused. */
140	export function isRequestId(value: unknown): value is AcpId {
141	  if (typeof value === "string") return value.length <= ACP_MAX_REQUEST_ID_CHARS;
142	  return typeof value === "number" && Number.isSafeInteger(value);
143	}
144	
145	export function rpcError(code: AcpErrorCode, message: string, data?: AcpErrorData): AcpError {
146	  return { code, message, ...(data ? { data } : {}) };
147	}
148	
149	function invalid(code: AcpErrorCode, message: string, id: AcpId | null = null, respond = true): Incoming {
150	  return { kind: "invalid", id, error: rpcError(code, message), respond };
151	}
152	
153	/** The answer to a line the reader reported as oversized. */
154	export function oversizedLineError(maxBytes: number = ACP_MAX_LINE_BYTES): AcpErrorResponse {
155	  return errorResponse(null, rpcError(ACP_ERROR.PARSE_ERROR, `a message is longer than ${maxBytes} bytes and was discarded`));
156	}
157	
158	/** Classifies one line. Never throws. */
159	export function parseMessage(line: string): Incoming {
160	  if (exceedsDepth(line)) return invalid(ACP_ERROR.PARSE_ERROR, `the message nests deeper than ${ACP_MAX_JSON_DEPTH} levels`);
161	  let raw: unknown;
162	  try {
163	    raw = JSON.parse(line);
164	  } catch {
165	    return invalid(ACP_ERROR.PARSE_ERROR, "the line is not valid JSON");
166	  }
167	  if (Array.isArray(raw)) return invalid(ACP_NV_BATCH_CODE, "batch requests are not supported");
168	  if (!raw || typeof raw !== "object") return invalid(ACP_ERROR.INVALID_REQUEST, "a message must be a JSON object");
169	  const message = raw as Record<string, unknown>;
170	  const hasId = own(message, "id");
171	  const id = hasId && isRequestId(message.id) ? message.id : null;
172	  const hasMethod = own(message, "method");
173	  // Something without a method is a reply (or nothing): it is never answered.
174	  const respond = hasMethod;
175	  if (message.jsonrpc !== JSONRPC_VERSION) return invalid(ACP_ERROR.INVALID_REQUEST, 'jsonrpc must be "2.0"', id, respond);
176	  if (hasMethod) {
177	    const method = message.method;
178	    if (typeof method !== "string" || !method || method.length > ACP_MAX_METHOD_CHARS) return invalid(ACP_ERROR.INVALID_REQUEST, "method must be a non-empty string", id);
179	    const params = own(message, "params") ? message.params : undefined;
180	    if (!hasId) return { kind: "notification", method, params };
181	    if (id === null) return invalid(ACP_ERROR.INVALID_REQUEST, "id must be a string or an integer");
182	    return { kind: "request", id, method, params };
183	  }
184	  if (id === null) return invalid(ACP_ERROR.INVALID_REQUEST, "a message needs a method, or the id of the request it answers", null, false);
185	  const hasResult = own(message, "result");
186	  const hasError = own(message, "error");
187	  if (hasResult === hasError) return invalid(ACP_ERROR.INVALID_REQUEST, "a response carries exactly one of result and error", id, false);
188	  if (hasResult) return { kind: "response", id, result: message.result };
189	  const error = message.error;
190	  if (!error || typeof error !== "object" || Array.isArray(error)) return invalid(ACP_ERROR.INVALID_REQUEST, "a response error must be an object", id, false);
191	  const { code, message: text } = error as Record<string, unknown>;
192	  if (typeof code !== "number" || typeof text !== "string") return invalid(ACP_ERROR.INVALID_REQUEST, "a response error needs a numeric code and a string message", id, false);
193	  return { kind: "response", id, error: { code, message: text, ...(own(error, "data") ? { data: (error as Record<string, unknown>).data } : {}) } };
194	}
195	
196	export function resultResponse<T>(id: AcpId, result: T): { jsonrpc: "2.0"; id: AcpId; result: T } {
197	  return { jsonrpc: JSONRPC_VERSION, id, result };
198	}
199	
200	export function errorResponse(id: AcpId | null, error: AcpError): AcpErrorResponse {
201	  return { jsonrpc: JSONRPC_VERSION, id, error };
202	}
203	
204	export function notification<M extends string, P>(method: M, params: P): { jsonrpc: "2.0"; method: M; params: P } {
205	  return { jsonrpc: JSONRPC_VERSION, method, params };
206	}
207	
208	export function request<M extends string, P>(id: number, method: M, params: P): { jsonrpc: "2.0"; id: number; method: M; params: P } {
209	  return { jsonrpc: JSONRPC_VERSION, id, method, params };
210	}
211	
212	/** The same expression as `encodeEvent` in protocol.ts (a test compares the two). */
213	const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;
214	
215	/**
216	 * One message as one line. `JSON.stringify` escapes every control character, so the only raw newline is the
217	 * terminator; a lone surrogate (a cut can split a pair) is replaced, because the client could not decode it.
218	 */
219	export function encodeMessage(message: object): string {
220	  const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.replace(LONE_SURROGATE, "�") : value);
221	  return JSON.stringify(message, wellFormed) + "\n";
222	}
223	
224	export type Settlement<T> =
225	  /** The first reply to an open request: `context` is what the request was opened with. */
226	  | { state: "matched"; context: T }
227	  /** A reply to a request that was already answered or abandoned (cancel, timeout, turn end). */
228	  | { state: "stale" }
229	  /** A reply to an id Nexus never issued (or one too old to remember), or an id that is not an integer. */
230	  | { state: "unknown" };
231	
232	const MAX_ID = 0x7fffffff;
233	
234	/**
235	 * Correlates agent-to-client requests with their replies. Ids are integers counted from a random 31-bit start, so a
236	 * reply written before the request exists matches nothing. Each id is answered at most once: the first reply is
237	 * `matched`, any later one `stale`. The last `tombstones` settled or abandoned ids are remembered for that distinction.
238	 */
239	export class RequestCorrelator<T> {
240	  private readonly open_ = new Map<number, T>();
241	  /** Insertion-ordered: the oldest tombstone is dropped first. */
242	  private readonly tombstones = new Set<number>();
243	  private next: number;
244	
245	  constructor(private readonly options: { start?: number; tombstones?: number } = {}) {
246	    this.next = options.start ?? randomInt(1, MAX_ID);
247	    if (!Number.isInteger(this.next) || this.next < 1 || this.next > MAX_ID) throw new RangeError("the first request id must be an integer from 1 to 2^31-1");
248	  }
249	
250	  get pending(): number {
251	    return this.open_.size;
252	  }
253	
254	  /** Registers a request and returns its id. */
255	  open(context: T): number {
256	    let id = this.next;
257	    while (this.open_.has(id)) id = id >= MAX_ID ? 1 : id + 1;
258	    this.next = id >= MAX_ID ? 1 : id + 1;
259	    this.tombstones.delete(id);
260	    this.open_.set(id, context);
261	    return id;
262	  }
263	
264	  /** Takes the reply to `id`. Only `matched` may lead to an action. */
265	  settle(id: unknown): Settlement<T> {
266	    if (typeof id !== "number" || !Number.isInteger(id)) return { state: "unknown" };
267	    if (this.open_.has(id)) {
268	      const context = this.open_.get(id) as T;
269	      this.close(id);
270	      return { state: "matched", context };
271	    }
272	    return this.tombstones.has(id) ? { state: "stale" } : { state: "unknown" };
273	  }
274	
275	  /** Closes a request without a reply (cancel, timeout, turn end, disconnect); a later reply to it is `stale`. */
276	  abandon(id: number): T | undefined {
277	    if (!this.open_.has(id)) return undefined;
278	    const context = this.open_.get(id);
279	    this.close(id);
280	    return context;
281	  }
282	
283	  private close(id: number): void {
284	    this.open_.delete(id);
285	    this.tombstones.add(id);
286	    const limit = this.options.tombstones ?? ACP_TOMBSTONE_COUNT;
287	    for (const oldest of this.tombstones) {
288	      if (this.tombstones.size <= limit) break;
289	      this.tombstones.delete(oldest);
290	    }
291	  }
292	}
293	/**
294	 * Validation of everything an ACP client sends. Each function takes the raw `params` (or `result`) and returns a typed
295	 * value or a -32602 error naming the field in `data.field`. Error messages are fixed text: no client string is echoed.
296	 *
297	 * Pure. The two checks that need the file system (the canonical form of `cwd`, whether a `file://` link lies inside
298	 * the workspace) take it as an argument (`AcpFs`), and never read a file's content.
299	 */
300	import path from "node:path";
301	import { fileURLToPath } from "node:url";
302	import {
303	  ACP_ERROR,
304	  ACP_MAX_CLIENT_FIELD_CHARS,
305	  ACP_MAX_CWD_CHARS,
306	  ACP_MAX_MCP_SERVERS_INSPECTED,
307	  ACP_MAX_PROMPT_BLOCKS,
308	  ACP_MAX_PROMPT_CHARS,
309	  ACP_MAX_RECEIPT_ID_CHARS,
310	  ACP_MAX_SESSION_ID_CHARS,
311	  ACP_MAX_TEXT_BLOCK_CHARS,
312	  ACP_MAX_URI_CHARS,
313	  ACP_NV_MAX_PROTOCOL_VERSION,
314	  ACP_PROTOCOL_VERSION,
315	} from "./types.js";
316	import type { AcpError, AcpId, AcpMcpServersIgnored, AcpPermissionOutcome } from "./types.js";
317	import { isRequestId } from "./jsonrpc.js";
318	
319	export type Validated<T> = { ok: true; value: T } | { ok: false; error: AcpError };
320	
321	/** The two file-system questions validation asks. Both throw when the path cannot be resolved or examined. */
322	export interface AcpFs {
323	  realpath(file: string): string;
324	  isDirectory(file: string): boolean;
325	}
326	
327	function fail(field: string, message: string): { ok: false; error: AcpError } {
328	  return { ok: false, error: { code: ACP_ERROR.INVALID_PARAMS, message, data: { field } } };
329	}
330	
331	function ok<T>(value: T): { ok: true; value: T } {
332	  return { ok: true, value };
333	}
334	
335	function record(value: unknown): Record<string, unknown> | undefined {
336	  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : undefined;
337	}
338	
339	/** An own member that is neither absent nor null. */
340	function present(object: Record<string, unknown>, key: string): boolean {
341	  return Object.hasOwn(object, key) && object[key] !== undefined && object[key] !== null;
342	}
343	
344	function member(object: Record<string, unknown>, key: string): unknown {
345	  return Object.hasOwn(object, key) ? object[key] : undefined;
346	}
347	
348	const CONTROL = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]/;
349	const CONTROL_RUNS = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g;
350	
351	/** Text bound for one line of a prompt or a log: control characters (newlines included) become a space, then it is cut. */
352	export function singleLine(text: string, max: number): string {
353	  return text.replace(CONTROL_RUNS, " ").trim().slice(0, max);
354	}
355	
356	export interface InitializeInput {
357	  /** The version the client asked for. The answer is `negotiatedProtocolVersion`. */
358	  protocolVersion: number;
359	  client: { name: string; version: string; title?: string } | null;
360	}
361	
362	/**
363	 * `clientCapabilities` and `_meta` are checked for shape and then dropped: the validated value carries neither, so
364	 * nothing downstream can consult what a client claims about itself.
365	 */
366	export function validateInitialize(params: unknown): Validated<InitializeInput> {
367	  const p = record(params);
368	  if (!p) return fail("params", "initialize requires a params object");
369	  const version = member(p, "protocolVersion");
370	  if (typeof version !== "number" || !Number.isInteger(version) || version < 0 || version > ACP_NV_MAX_PROTOCOL_VERSION) {
371	    return fail("protocolVersion", `protocolVersion must be an integer from 0 to ${ACP_NV_MAX_PROTOCOL_VERSION}`);
372	  }
373	  if (present(p, "clientCapabilities") && !record(p.clientCapabilities)) return fail("clientCapabilities", "clientCapabilities must be an object");
374	  let client: InitializeInput["client"] = null;
375	  if (present(p, "clientInfo")) {
376	    const info = record(p.clientInfo);
377	    if (!info) return fail("clientInfo", "clientInfo must be an object");
378	    const text = (key: string, required: boolean): Validated<string | undefined> => {
379	      if (!present(info, key)) return required ? fail(`clientInfo.${key}`, `clientInfo.${key} must be a non-empty string`) : ok(undefined);
380	      const value = info[key];
381	      if (typeof value !== "string" || !value.trim()) return fail(`clientInfo.${key}`, `clientInfo.${key} must be a non-empty string`);
382	      if (value.length > ACP_MAX_CLIENT_FIELD_CHARS) return fail(`clientInfo.${key}`, `clientInfo.${key} is longer than ${ACP_MAX_CLIENT_FIELD_CHARS} characters`);
383	      if (CONTROL.test(value)) return fail(`clientInfo.${key}`, `clientInfo.${key} must not contain control characters`);
384	      return ok(value);
385	    };
386	    const name = text("name", true);
387	    if (!name.ok) return name;
388	    const clientVersion = text("version", true);
389	    if (!clientVersion.ok) return clientVersion;
390	    const title = text("title", false);
391	    if (!title.ok) return title;
392	    client = { name: name.value as string, version: clientVersion.value as string, ...(title.value !== undefined ? { title: title.value } : {}) };
393	  }
394	  return ok({ protocolVersion: version, client });
395	}
396	
397	/**
398	 * The version to answer `initialize` with: the requested one when Nexus supports it, else the latest Nexus supports
399	 * (published specification, initialization). Nexus supports one version, so this is that version either way.
400	 */
401	export function negotiatedProtocolVersion(_requested: number): typeof ACP_PROTOCOL_VERSION {
402	  return ACP_PROTOCOL_VERSION;
403	}
404	
405	/**
406	 * The part of the `cwd` rule that needs no file system: a string, absolute ("MUST be an absolute path", published
407	 * specification, session-setup), bounded, with no NUL and no line break.
408	 */
409	export function validateCwdShape(value: unknown, field = "cwd"): Validated<string> {
410	  if (typeof value !== "string" || !value) return fail(field, "cwd must be a non-empty string");
411	  if (value.length > ACP_MAX_CWD_CHARS) return fail(field, `cwd is longer than ${ACP_MAX_CWD_CHARS} characters`);
412	  if (/[\0\r\n]/.test(value)) return fail(field, "cwd must not contain a NUL or a line break");
413	  if (!path.isAbsolute(value)) return fail(field, "cwd must be an absolute path");
414	  return ok(value);
415	}
416	
417	/**
418	 * The part that does: the real path of `cwd` (symlinks resolved), which must be a directory. The canonical path is what
419	 * the session runs in, and it passes the shape rule again, because a link can lead to a name the rule refuses.
420	 */
421	export function canonicalCwd(cwd: string, fs: AcpFs, field = "cwd"): Validated<string> {
422	  const shaped = validateCwdShape(cwd, field);
423	  if (!shaped.ok) return shaped;
424	  let real: string;
425	  try {
426	    real = fs.realpath(shaped.value);
427	    if (!fs.isDirectory(real)) return fail(field, "cwd is not a directory");
428	  } catch {
429	    return fail(field, "cwd does not exist or cannot be read");
430	  }
431	  return validateCwdShape(real, field);
432	}
433	
434	/** The exact shape `SessionManager.generateSessionId` writes. `latest`, a prefix and a file name are not session ids here. */
435	const SESSION_ID = /^session_\d{8}_\d{6}_[a-z0-9]{8}$/;
436	
437	export function validateSessionId(value: unknown, field = "sessionId"): Validated<string> {
438	  if (typeof value !== "string" || value.length > ACP_MAX_SESSION_ID_CHARS || !SESSION_ID.test(value)) {
439	    return fail(field, "sessionId must be a complete Nexus session id");
440	  }
441	  return ok(value);
442	}
443	
444	function mcpServers(p: Record<string, unknown>): Validated<AcpMcpServersIgnored> {
445	  const servers = member(p, "mcpServers");
446	  if (!Array.isArray(servers)) return fail("mcpServers", "mcpServers is required and must be an array");
447	  const names: string[] = [];
448	  for (const entry of servers.slice(0, ACP_MAX_MCP_SERVERS_INSPECTED)) {
449	    const name = record(entry) ? member(entry as Record<string, unknown>, "name") : undefined;
450	    names.push(typeof name === "string" ? singleLine(name, ACP_MAX_CLIENT_FIELD_CHARS) : "");
451	  }
452	  return ok({ count: servers.length, names });
453	}
454	
455	/** Session options the specification defines and Nexus does not support: refused, never silently ignored. */
456	function unsupportedSessionOptions(p: Record<string, unknown>): { ok: false; error: AcpError } | undefined {
457	  if (present(p, "additionalDirectories")) {
458	    const directories = p.additionalDirectories;
459	    if (!Array.isArray(directories)) return fail("additionalDirectories", "additionalDirectories must be an array");
460	    if (directories.length > 0) return fail("additionalDirectories", "additional directories are not supported: a session has one workspace, cwd");
461	  }
462	  if (present(p, "systemPrompt")) return fail("systemPrompt", "a client-supplied system prompt is not supported");
463	  return undefined;
464	}
465	
466	export interface NewSessionInput {
467	  /** As sent, shape-checked. Run it through `canonicalCwd` before use. */
468	  cwd: string;
469	  /** What the client asked to connect, for the report only: none of it is connected. */
470	  mcpServers: AcpMcpServersIgnored;
471	}
472	
473	export function validateNewSession(params: unknown): Validated<NewSessionInput> {
474	  const p = record(params);
475	  if (!p) return fail("params", "session/new requires a params object");
476	  const cwd = validateCwdShape(member(p, "cwd"));
477	  if (!cwd.ok) return cwd;
478	  const servers = mcpServers(p);
479	  if (!servers.ok) return servers;
480	  const unsupported = unsupportedSessionOptions(p);
481	  if (unsupported) return unsupported;
482	  return ok({ cwd: cwd.value, mcpServers: servers.value });
483	}
484	
485	export interface LoadSessionInput extends NewSessionInput {
486	  sessionId: string;
487	}
488	
489	export function validateLoadSession(params: unknown): Validated<LoadSessionInput> {
490	  const p = record(params);
491	  if (!p) return fail("params", "session/load requires a params object");
492	  const sessionId = validateSessionId(member(p, "sessionId"));
493	  if (!sessionId.ok) return sessionId;
494	  const rest = validateNewSession(p);
495	  if (!rest.ok) return rest;
496	  return ok({ sessionId: sessionId.value, ...rest.value });
497	}
498	
499	/**
500	 * A `resource_link` as one line of prompt text. A `file://` URI whose real path lies inside the workspace becomes
501	 * `Referenced file: <path relative to the workspace>`; anything else becomes `Reference: <the URI, on one line>`.
502	 * Nothing is read or fetched: the agent reaches the file, if it wants it, through its own gated tools.
503	 * `workspace` must already be canonical.
504	 */
505	export function resourceLinkLine(uri: string, workspace: string, fs: AcpFs): string {
506	  if (/^file:\/\//i.test(uri)) {
507	    try {
508	      const real = fs.realpath(fileURLToPath(new URL(uri)));
509	      const relative = path.relative(workspace, real);
510	      const inside = relative !== "" && !path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`);
511	      if (inside && !CONTROL.test(relative)) return `Referenced file: ${relative}`;
512	    } catch {
513	      // Not a path that exists here: it stays an opaque reference.
514	    }
515	  }
516	  return `Reference: ${singleLine(uri, ACP_MAX_URI_CHARS)}`;
517	}
518	
519	export interface PromptInput {
520	  sessionId: string;
521	  /** The prompt as the sidecar receives it: text blocks and reference lines, one per line group, in order. */
522	  text: string;
523	}
524	
525	const REFUSED_BLOCKS: Record<string, string> = {
526	  image: "image content is not supported",
527	  audio: "audio content is not supported",
528	  resource: "embedded resources are not supported; send a resource_link",
529	};
530	
531	/**
532	 * `session/prompt`: content blocks to prompt text. `text` is taken as it is; `resource_link` becomes a reference line
533	 * (see `resourceLinkLine`); `image`, `audio` and `resource` are refused, naming the block.
534	 */
535	export function validatePrompt(params: unknown, context: { workspace: string; fs: AcpFs }): Validated<PromptInput> {
536	  const p = record(params);
537	  if (!p) return fail("params", "session/prompt requires a params object");
538	  const sessionId = validateSessionId(member(p, "sessionId"));
539	  if (!sessionId.ok) return sessionId;
540	  const blocks = member(p, "prompt");
541	  if (!Array.isArray(blocks) || blocks.length === 0) return fail("prompt", "prompt must be a non-empty array of content blocks");
542	  if (blocks.length > ACP_MAX_PROMPT_BLOCKS) return fail("prompt", `prompt has more than ${ACP_MAX_PROMPT_BLOCKS} content blocks`);
543	  const parts: string[] = [];
544	  let total = 0;
545	  for (let i = 0; i < blocks.length; i++) {
546	    const field = `prompt[${i}]`;
547	    const block = record(blocks[i]);
548	    if (!block) return fail(field, `prompt block ${i} must be an object`);
549	    const type = member(block, "type");
550	    let part: string;
551	    if (type === "text") {
552	      const text = member(block, "text");
553	      if (typeof text !== "string") return fail(`${field}.text`, `prompt block ${i}: text must be a string`);
554	      if (text.length > ACP_MAX_TEXT_BLOCK_CHARS) return fail(`${field}.text`, `prompt block ${i}: text is longer than ${ACP_MAX_TEXT_BLOCK_CHARS} characters`);
555	      if (text.includes("\0")) return fail(`${field}.text`, `prompt block ${i}: text must not contain a NUL`);
556	      part = text;
557	    } else if (type === "resource_link") {
558	      const uri = member(block, "uri");
559	      if (typeof uri !== "string" || !uri) return fail(`${field}.uri`, `prompt block ${i}: uri must be a non-empty string`);
560	      if (uri.length > ACP_MAX_URI_CHARS) return fail(`${field}.uri`, `prompt block ${i}: uri is longer than ${ACP_MAX_URI_CHARS} characters`);
561	      part = resourceLinkLine(uri, context.workspace, context.fs);
562	    } else if (typeof type === "string" && Object.hasOwn(REFUSED_BLOCKS, type)) {
563	      return fail(field, `prompt block ${i}: ${REFUSED_BLOCKS[type]}`);
564	    } else {
565	      return fail(`${field}.type`, `prompt block ${i}: unknown content type`);
566	    }
567	    total += part.length + (parts.length ? 1 : 0);
568	    if (total > ACP_MAX_PROMPT_CHARS) return fail("prompt", `the prompt is longer than ${ACP_MAX_PROMPT_CHARS} characters`);
569	    parts.push(part);
570	  }
571	  const text = parts.join("\n");
572	  if (!text.trim()) return fail("prompt", "the prompt has no text");
573	  return ok({ sessionId: sessionId.value, text });
574	}
575	
576	export function validateCancel(params: unknown): Validated<{ sessionId: string }> {
577	  const p = record(params);
578	  if (!p) return fail("params", "session/cancel requires a params object");
579	  const sessionId = validateSessionId(member(p, "sessionId"));
580	  return sessionId.ok ? ok({ sessionId: sessionId.value }) : sessionId;
581	}
582	
583	/** `$/cancel_request`: the id of the request to cancel. */
584	export function validateCancelRequest(params: unknown): Validated<{ requestId: AcpId }> {
585	  const p = record(params);
586	  if (!p) return fail("params", "$/cancel_request requires a params object");
587	  const requestId = member(p, "requestId");
588	  if (!isRequestId(requestId)) return fail("requestId", "requestId must be a string or an integer");
589	  return ok({ requestId });
590	}
591	
592	export function validateReceiptGet(params: unknown): Validated<{ sessionId: string; receiptId?: string }> {
593	  const p = record(params);
594	  if (!p) return fail("params", "the receipt request requires a params object");
595	  const sessionId = validateSessionId(member(p, "sessionId"));
596	  if (!sessionId.ok) return sessionId;
597	  if (!present(p, "receiptId")) return ok({ sessionId: sessionId.value });
598	  const receiptId = p.receiptId;
599	  if (typeof receiptId !== "string" || !receiptId || receiptId.length > ACP_MAX_RECEIPT_ID_CHARS || CONTROL.test(receiptId)) {
600	    return fail("receiptId", `receiptId must be a non-empty string of at most ${ACP_MAX_RECEIPT_ID_CHARS} characters`);
601	  }
602	  return ok({ sessionId: sessionId.value, receiptId });
603	}
604	
605	/**
606	 * The shape of the `result` of a reply to `session/request_permission`: `{outcome: {outcome: "selected", optionId}}`
607	 * or `{outcome: {outcome: "cancelled"}}`. Shape only: which option id approves is decided in one place,
608	 * `permissionReplyToCommand` in mapping.ts. There is nobody to send this error to: the caller denies.
609	 */
610	export function validatePermissionResult(result: unknown): Validated<AcpPermissionOutcome> {
611	  const r = record(result);
612	  if (!r) return fail("result", "a permission result must be an object");
613	  const outcome = record(member(r, "outcome"));
614	  if (!outcome) return fail("outcome", "a permission result needs an outcome object");
615	  const kind = member(outcome, "outcome");
616	  if (kind === "cancelled") return ok({ outcome: "cancelled" });
617	  if (kind !== "selected") return fail("outcome.outcome", "the outcome must be selected or cancelled");
618	  const optionId = member(outcome, "optionId");
619	  if (typeof optionId !== "string") return fail("outcome.optionId", "a selected outcome needs a string optionId");
620	  return ok({ outcome: "selected", optionId });
621	}

