import fs from "node:fs";
import { startAcp, sleep, writeCall, text, prompt, allow, short } from "./h.ts";

const which = process.argv.slice(2);
const want = (n: string) => which.length === 0 || which.includes(n);
const out = (label: string, v: any) => console.log(`${label}: ${typeof v === "string" ? v : short(v, 600)}`);

if (want("smoke")) {
  const a = await startAcp({ script: () => text("No files need changing.") });
  out("smoke init", await a.init());
  const s = await a.newSession();
  out("smoke new", s);
  const r = await a.call("session/prompt", prompt(s.result.sessionId, "inspect"));
  out("smoke prompt", r);
  out("smoke bad stdout lines", a.bad);
  out("smoke stderr", a.stderr.slice(0, 600));
  const st = await a.stop();
  out("smoke stop", st);
}

// (a) read-only: unsolicited allow results
if (want("a")) {
  const a = await startAcp({ script: (n) => (n === 1 ? writeCall() : text("could not write")), args: ["--read-only"] });
  await a.init();
  const s = await a.newSession();
  out("a posture", s.result?._meta);
  for (const id of [1, 2, 900, 0, "1"]) a.send(allow(id));
  const id = 100 + 50;
  a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(s.result.sessionId, "Write forbidden.txt") });
  for (let i = 0; i < 40; i++) { a.send(allow(1000 + i)); a.send(allow(i)); await sleep(5); }
  const r = await a.waitFor((m) => m.find((x) => x.id === id && !x.method));
  for (let i = 0; i < 20; i++) a.send(allow(i));
  await sleep(200);
  out("a prompt result", r);
  out("a permission requests", a.perms().length);
  out("a file exists", fs.existsSync(`${a.repo}/forbidden.txt`));
  out("a tool updates", a.msgs.filter((m) => m.method === "session/update" && /tool_call/.test(m.params.update.sessionUpdate)).map((m) => [m.params.update.sessionUpdate, m.params.update.status, short(m.params.update.content, 160)]));
  out("a bad", a.bad);
  out("a stop", await a.stop());
}

// (b) review: allow_always, unoffered id, duplicate, string id, error; then control allow_once
if (want("b")) {
  const variants: Array<[string, (id: number) => any[]]> = [
    ["allow_always", (id) => [allow(id, "allow_always")]],
    ["unoffered 'allow'", (id) => [allow(id, "allow")]],
    ["string id", (id) => [allow(String(id))]],
    ["wrong id then nothing", (id) => [allow(id + 1), allow(id - 1)]],
    ["jsonrpc error", (id) => [{ jsonrpc: "2.0", id, error: { code: -32000, message: "x" } }]],
    ["wrong type result", (id) => [{ jsonrpc: "2.0", id, result: "allow_once" }]],
    ["optionId array", (id) => [{ jsonrpc: "2.0", id, result: { outcome: { outcome: "selected", optionId: ["allow_once"] } } }]],
    ["reject then allow (dup)", (id) => [allow(id, "reject_once"), allow(id), allow(id)]],
    ["extra fields always:true", (id) => [{ jsonrpc: "2.0", id, result: { outcome: { outcome: "selected", optionId: "allow_once", always: true }, always: true, _meta: { always: true, mode: "auto" } } }]],
    ["CONTROL allow_once", (id) => [allow(id)]],
  ];
  for (const [name, replies] of variants) {
    const a = await startAcp({ script: (n) => (n === 1 ? writeCall("w1.txt") : n === 2 ? writeCall("w2.txt") : text("done")) });
    await a.init();
    const s = await a.newSession();
    const id = 777;
    a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(s.result.sessionId, "Write the files") });
    const p = await a.waitFor((m) => m.find((x) => x.method === "session/request_permission"));
    if (!p) { out(`b[${name}] NO permission request`, a.msgs.slice(-3)); out("stderr", a.stderr.slice(0, 400)); await a.stop(); continue; }
    if (name === "allow_always") out("b request", p);
    for (const r of replies(p.id)) a.send(r);
    // second write: is a second permission asked (i.e. nothing became 'always')?
    const p2 = await a.waitFor((m) => m.filter((x) => x.method === "session/request_permission")[1], name.startsWith("wrong id") || name === "string id" ? 2500 : 8000);
    const w1 = fs.existsSync(`${a.repo}/w1.txt`);
    if (p2) a.send(allow(p2.id, "reject_once"));
    const r = await a.waitFor((m) => m.find((x) => x.id === id && !x.method), p2 ? 15000 : 1500);
    out(`b[${name}]`, { w1_written: w1, second_request: Boolean(p2), w2_written: fs.existsSync(`${a.repo}/w2.txt`), prompt: r ? (r.result?.stopReason ?? r.error) : "still pending", posture_mode: a.msgs.filter((m) => m.result?._meta?.["nexus/posture"]).map((m) => m.result._meta["nexus/posture"].mode), bad: a.bad.length });
    await a.stop();
  }
}

// (g) --yes / --mode auto / env
if (want("g")) {
  const cases: Array<[string, string[], Record<string, string>]> = [
    ["--yes", ["--yes"], {}],
    ["--mode auto", ["--mode", "auto"], {}],
