// Review harness: drives the real `nexus acp` entry as a child process against a scripted local gateway.
import { spawn, spawnSync, type ChildProcess } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
const WT = "/home/mike/nexus-wt/rev741/cli";
const { startGateway, makeRepo, makeHome } = await import(`${WT}/test/helpers/fixtures.ts`);
export { startGateway, makeRepo, makeHome };

export type Acp = Awaited<ReturnType<typeof startAcp>>;
export const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
export const INIT = { jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: 1, clientInfo: { name: "rev", version: "1" }, clientCapabilities: {} } };

export async function startAcp(o: { script: (n: number, body?: any) => any; args?: string[]; env?: Record<string, string>; cwd?: string; home?: string; repo?: string; homeSetup?: (home: string) => void; repoFiles?: Record<string, string> }) {
  const gateway = await startGateway(o.script);
  const repo = o.repo ?? makeRepo(o.repoFiles ?? {});
  const home = o.home ?? makeHome();
  o.homeSetup?.(home);
  const env = { PATH: process.env.PATH!, HOME: home, XDG_CONFIG_HOME: `${home}/.config`, TMPDIR: os.tmpdir(), ...(o.env ?? {}) };
  const child: ChildProcess = spawn(process.execPath, ["--import", `file://${WT}/node_modules/tsx/dist/loader.mjs`, `${WT}/src/index.ts`, "-e", gateway.url, "-m", "m", ...(o.args ?? []), "acp"], { cwd: o.cwd ?? repo, env, stdio: ["pipe", "pipe", "pipe"] });
  const msgs: any[] = [];
  const bad: string[] = [];
  let stderr = "";
  let buf = "";
  let exit: { code: number | null; signal: string | null } | undefined;
  child.stdout!.on("data", (c) => {
    buf += c.toString("utf8");
    let i;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i); buf = buf.slice(i + 1);
      try { const m = JSON.parse(line); if (m?.jsonrpc !== "2.0") bad.push(line); else msgs.push(m); } catch { bad.push(line); }
    }
  });
  child.stderr!.on("data", (c) => { stderr += c.toString("utf8"); });
  child.on("exit", (code, signal) => { exit = { code, signal }; });
  child.stdin!.on("error", () => {});
  const send = (m: object) => child.stdin!.write(JSON.stringify(m) + "\n");
  const raw = (s: string | Buffer) => child.stdin!.write(s);
  const waitFor = async (pred: (m: any[]) => any, ms = 20000, label = "") => {
    const end = Date.now() + ms;
    while (Date.now() < end) { const r = pred(msgs); if (r) return r; if (exit) break; await sleep(20); }
    const r = pred(msgs); if (r) return r;
    return undefined;
  };
  const reply = (id: any) => waitFor((m) => m.find((x) => x.id === id && !x.method && (x.result !== undefined || x.error)), 20000);
  const init = async () => { send(INIT); return reply(1); };
  let nextId = 100;
  const call = async (method: string, params: any, ms = 20000) => { const id = nextId++; send({ jsonrpc: "2.0", id, method, params }); return waitFor((m) => m.find((x) => x.id === id && !x.method), ms); };
  const newSession = async (cwd = repo) => (await call("session/new", { cwd, mcpServers: [] }));
  const perms = () => msgs.filter((m) => m.method === "session/request_permission");
  const waitExit = async (ms = 15000) => { const end = Date.now() + ms; while (!exit && Date.now() < end) await sleep(25); return exit; };
  const stop = async () => {
    if (!exit) { child.stdin!.end(); await waitExit(8000); }
    let forced = false;
    if (!exit) { forced = true; child.kill("SIGKILL"); await waitExit(3000); }
    await gateway.close();
    fs.rmSync(repo, { recursive: true, force: true });
    if (!o.home) fs.rmSync(home, { recursive: true, force: true });
    return { exit, forced };
  };
  return { child, pid: child.pid!, gateway, repo, home, msgs, bad, send, raw, waitFor, reply, init, call, newSession, perms, waitExit, stop, get stderr() { return stderr; }, get exit() { return exit; }, get partial() { return buf; } };
}

export function rssKb(pid: number): number {
  try { return Number(/VmRSS:\s+(\d+)/.exec(fs.readFileSync(`/proc/${pid}/status`, "utf8"))?.[1] ?? -1); } catch { return -1; }
}
export function alive(pid: number): boolean {
  try { process.kill(pid, 0); } catch { return false; }
  const ps = spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" });
  return ps.status === 0 && !ps.stdout.trim().startsWith("Z");
}
export function descendants(pid: number): number[] {
  const ps = spawnSync("ps", ["-e", "-o", "pid=,ppid="], { encoding: "utf8" });
  const kids = new Map<number, number[]>();
  for (const l of ps.stdout.split("\n")) { const [p, pp] = l.trim().split(/\s+/).map(Number); if (p) (kids.get(pp) ?? kids.set(pp, []).get(pp)!).push(p); }
