    await a.init();
    const s = await a.newSession();
    const id = 777;
    a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(s.result.sessionId, "Write the files") });
    const p = await a.waitFor((m) => m.find((x) => x.method === "session/request_permission"));
    if (!p) { out(`b[${name}] NO permission request`, a.msgs.slice(-3)); out("stderr", a.stderr.slice(0, 400)); await a.stop(); continue; }
    if (name === "allow_always") out("b request", p);
    for (const r of replies(p.id)) a.send(r);
    // second write: is a second permission asked (i.e. nothing became 'always')?
    const p2 = await a.waitFor((m) => m.filter((x) => x.method === "session/request_permission")[1], name.startsWith("wrong id") || name === "string id" ? 2500 : 8000);
    const w1 = fs.existsSync(`${a.repo}/w1.txt`);
    if (p2) a.send(allow(p2.id, "reject_once"));
    const r = await a.waitFor((m) => m.find((x) => x.id === id && !x.method), p2 ? 15000 : 1500);
    out(`b[${name}]`, { w1_written: w1, second_request: Boolean(p2), w2_written: fs.existsSync(`${a.repo}/w2.txt`), prompt: r ? (r.result?.stopReason ?? r.error) : "still pending", posture_mode: a.msgs.filter((m) => m.result?._meta?.["nexus/posture"]).map((m) => m.result._meta["nexus/posture"].mode), bad: a.bad.length });
    await a.stop();
  }
}

// (g) --yes / --mode auto / env
if (want("g")) {
  const cases: Array<[string, string[], Record<string, string>]> = [
    ["--yes", ["--yes"], {}],
    ["--mode auto", ["--mode", "auto"], {}],
    ["NEXUS_APPROVAL_MODE=auto", [], { NEXUS_APPROVAL_MODE: "auto" }],
    ["default", [], {}],
  ];
  for (const [name, args, env] of cases) {
    const a = await startAcp({ script: (n) => (n === 1 ? writeCall("auto.txt") : n === 2 ? { kind: "tools", calls: [{ name: "run_command", args: { command: "touch ran_by_command.txt" } }] } : text("done")), args, env });
    const init = await a.init();
    if (!init) { out(`g[${name}] no init; exit`, a.exit); out("stderr", a.stderr.slice(0, 500)); await a.stop(); continue; }
    const s = await a.newSession();
    const id = 778;
    a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(s.result.sessionId, "Write auto.txt") });
    const r = await a.waitFor((m) => m.find((x) => x.id === id && !x.method), 6000);
    out(`g[${name}]`, { posture: s.result?._meta?.["nexus/posture"], permission_requests: a.perms().length, written: fs.existsSync(`${a.repo}/auto.txt`), command_ran: fs.existsSync(`${a.repo}/ran_by_command.txt`), prompt: r ? (r.result?.stopReason ?? r.error) : "pending (awaiting permission)", stderr: a.stderr.slice(0, 200) });
    await a.stop();
  }
}

