import fs from "node:fs";
import path from "node:path";
import { startAcp, sleep, writeCall, text, prompt, allow, short, rssKb, alive, descendants, pidArgs, tmpdir, makeRepo } from "./h.mts";

const which = process.argv.slice(2);
const want = (n: string) => which.includes(n);
const out = (label: string, v: any) => console.log(`${label}: ${typeof v === "string" ? v : short(v, 700)}`);
const res = (r: any) => (r ? (r.result !== undefined ? { result: r.result } : { error: r.error }) : "NO REPLY");

// (c) cwd variants
if (want("c")) {
  const a = await startAcp({ script: () => text() });
  await a.init();
  const outside = tmpdir("rev741-outside-");
  const link = path.join(tmpdir("rev741-link-"), "ln"); fs.symlinkSync(outside, link);
  const file = path.join(outside, "afile"); fs.writeFileSync(file, "x");
  const cases: Array<[string, any]> = [["relative '.'", "."], ["relative 'sub/dir'", "sub/dir"], ["file", file], ["missing", "/nonexistent/rev741"], ["number", 5], ["with newline", `${outside}\n`], ["dotdot (non-canonical)", `${outside}/../${path.basename(outside)}`]];
  for (const [name, cwd] of cases) out(`c[${name}]`, res(await a.call("session/new", { cwd, mcpServers: [] })));
  const viaLink = await a.call("session/new", { cwd: link, mcpServers: [] });
  out("c[symlink -> outside launch dir]", res(viaLink));
  const outsideS = await a.call("session/new", { cwd: outside, mcpServers: [{ name: "evil", command: "/bin/sh", args: ["-c", `touch ${outside}/MCP_STARTED`], env: [] }] });
  out("c[outside launch dir + client mcpServers]", res(outsideS));
  const root = await a.call("session/new", { cwd: "/", mcpServers: [] });
  out("c[cwd '/']", res(root));
  await sleep(500);
  out("c client MCP server started?", fs.existsSync(`${outside}/MCP_STARTED`));
  out("c extra opts", [res(await a.call("session/new", { cwd: outside, mcpServers: [], additionalDirectories: ["/etc"] })), res(await a.call("session/new", { cwd: outside, mcpServers: [], systemPrompt: "x" }))]);
  out("c bad", a.bad);
  out("c stop", await a.stop());
  fs.rmSync(outside, { recursive: true, force: true }); fs.rmSync(path.dirname(link), { recursive: true, force: true });
}

// (d) sessions: 5th, and whether anything frees a slot
if (want("d")) {
  const a = await startAcp({ script: () => text() });
  await a.init();
  const base = descendants(a.pid).length;
  const fds = () => { try { return fs.readdirSync(`/proc/${a.pid}/fd`).length; } catch { return -1; } };
  const fd0 = fds(), rss0 = rssKb(a.pid);
  const ids: string[] = [];
  for (let i = 0; i < 5; i++) { const s = await a.newSession(); out(`d session ${i + 1}`, s?.result?.sessionId ?? s?.error); if (s?.result) ids.push(s.result.sessionId); }
  out("d after 4 sessions", { descendants_before: base, descendants_now: descendants(a.pid).map(pidArgs), fds_before: fd0, fds_now: fds(), rss_kb_before: rss0, rss_kb_now: rssKb(a.pid) });
  for (const m of ["session/close", "session/delete", "session/list"]) out(`d ${m}`, res(await a.call(m, { sessionId: ids[0] })));
  a.send({ jsonrpc: "2.0", method: "session/cancel", params: { sessionId: ids[0] } });
  await sleep(300);
  out("d 5th after cancel/close attempts", res(await a.newSession()));
  out("d load existing id while active", res(await a.call("session/load", { sessionId: ids[0], cwd: a.repo, mcpServers: [] })));
  // pending-request cap: 40 concurrent prompts to one session + other requests
  out("d stop", await a.stop());
}

// (e) oversized line in small chunks, watching memory
if (want("e")) {
  const a = await startAcp({ script: () => text() });
  await a.init();
  await sleep(500);
  const rss0 = rssKb(a.pid);
  const chunk = Buffer.alloc(64 * 1024, 0x61);
  let peak = rss0;
  const total = 256 * 1024 * 1024;
  let sent = 0;
  const t0 = Date.now();
  while (sent < total) {
    if (!a.child.stdin!.write(chunk)) await new Promise((r) => a.child.stdin!.once("drain", r));
    sent += chunk.length;
    if (sent % (8 * 1024 * 1024) === 0) { const r = rssKb(a.pid); if (r > peak) peak = r; }
  }
  out("e sent MiB without newline", { mib: sent / 1048576, ms: Date.now() - t0, rss_kb_before: rss0, rss_kb_peak: peak, rss_kb_after: rssKb(a.pid), errors_so_far: a.msgs.filter((m) => m.error).map((m) => m.error) });
  a.raw("\n");
  out("e still serves after newline", res(await a.call("session/new", { cwd: a.repo, mcpServers: [] })));
  // second and third oversized lines -> connection closes
  for (let k = 0; k < 2; k++) { for (let i = 0; i < 70; i++) { if (!a.child.stdin!.write(chunk)) await new Promise((r) => a.child.stdin!.once("drain", r)); } a.raw("\n"); await sleep(200); }
  await sleep(500);
  out("e oversized errors total", a.msgs.filter((m) => m.error?.code === -32700).length);
  const after = await Promise.race([a.call("session/new", { cwd: a.repo, mcpServers: [] }, 3000), sleep(3500)]);
  out("e request after 3 oversized", res(after));
  out("e process exited by itself?", (await a.waitExit(5000)) ?? "NO (still running, stdin open)");
  out("e bad", a.bad.length);
  out("e stop", await a.stop());
}

// (e2) framing: depth bomb, batch, malformed, unknown method/notification, pre-initialize, repeated initialize
if (want("e2")) {
  const a = await startAcp({ script: () => text() });
  a.send({ jsonrpc: "2.0", id: 5, method: "session/new", params: { cwd: a.repo, mcpServers: [] } });
  out("e2 before initialize", res(await a.reply(5)));
