  out(`f adapter exit after ${term ? "SIGTERM" : "EOF"}`, { exit: ex ?? "DID NOT EXIT in 20s", ms: Date.now() - t0 });
  await sleep(500);
  out("f survivors", kids.filter(alive).map((k) => `${k}:${pidArgs(k).slice(0, 60)}`));
  out("f prompt reply before exit", res(a.msgs.find((x) => x.id === 50 && !x.method)));
  out("f bad", a.bad.length);
  for (const k of kids) if (alive(k)) { try { process.kill(k, "SIGKILL"); } catch {} }
  out("f stop", await a.stop());
  out("f adapter alive after stop", alive(a.pid));
}

// idle: EOF / SIGTERM with no turn running
if (want("idle")) {
  for (const how of ["EOF", "SIGTERM", "SIGINT"]) {
    const a = await startAcp({ script: () => text() });
    await a.init();
    const s = await a.newSession();
    const t0 = Date.now();
    if (how === "EOF") a.child.stdin!.end(); else a.child.kill(how as any);
    const ex = await a.waitExit(12000);
    out(`idle ${how}`, { exit: ex ?? "DID NOT EXIT in 12s", ms: Date.now() - t0, session: Boolean(s?.result) });
    await a.stop();
  }
}

