import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
import { startAcp, sleep, writeCall, text, prompt, allow, short, rssKb, alive, descendants, pidArgs, tmpdir, makeRepo, makeHome } from "./h.mts";

const which = process.argv.slice(2);
const want = (n: string) => which.includes(n);
const out = (label: string, v: any) => console.log(`${label}: ${typeof v === "string" ? v : short(v, 900)}`);
const res = (r: any) => (r ? (r.result !== undefined ? { result: r.result } : { error: r.error }) : "NO REPLY");
const toolUpdates = (a: any) => a.msgs.filter((m: any) => m.method === "session/update" && /tool_call/.test(m.params.update.sessionUpdate)).map((m: any) => [m.params.update.sessionUpdate, m.params.update.status, short(m.params.update.content?.[0]?.content?.text ?? m.params.update.title, 170)]);

/** One gate case in review mode: run a turn whose first model reply is `call`; flood allow results; report. */
async function gate(name: string, call: any, o: { repoFiles?: Record<string, string>; homeSetup?: (h: string) => void; check: (repo: string) => any; answer?: "allow" | "none"; args?: string[] }) {
  const a = await startAcp({ script: (n) => (n === 1 ? { kind: "tools", calls: [call] } : text("done")), repoFiles: o.repoFiles, homeSetup: o.homeSetup, args: o.args });
  await a.init();
  const s = await a.newSession();
  const id = 60;
  a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(s.result.sessionId, "do it") });
  let flood = true;
  const flooder = (async () => { let i = 0; while (flood) { a.send(allow(i++)); a.send(allow(1000 + i)); for (const p of a.perms()) if (o.answer !== "allow") { /* never answer real ones unless asked */ } await sleep(10); } })();
  let r: any;
  const end = Date.now() + 75000;
  const answered = new Set<number>();
  while (Date.now() < end && !(r = a.msgs.find((x) => x.id === id && !x.method))) {
    if (o.answer === "allow") for (const p of a.perms()) if (!answered.has(p.id)) { answered.add(p.id); a.send(allow(p.id)); }
    await sleep(25);
  }
  flood = false; await flooder;
  out(`gate[${name}]`, { permission_requests: a.perms().map((p: any) => p.params.toolCall.title), answered_allow: answered.size, effect: o.check(a.repo), prompt: r ? (r.result?.stopReason ?? r.error) : "still pending after 75s", tools: toolUpdates(a), bad: a.bad.length });
  await a.stop();
}

if (want("g-ro")) await gate("read-only + run_command", { name: "run_command", args: { command: "touch ro_cmd.txt" } }, { args: ["--read-only"], check: (r) => ({ ro_cmd_exists: fs.existsSync(`${r}/ro_cmd.txt`) }) });
if (want("g-rule")) await gate("forbidden command rule", { name: "run_command", args: { command: "touch rule_hit.txt" } }, {
  homeSetup: (h) => { fs.mkdirSync(`${h}/.config/nexus`, { recursive: true, mode: 0o700 }); fs.writeFileSync(`${h}/.config/nexus/command_rules.json`, JSON.stringify({ version: 1, rules: [{ prefix: ["touch"], decision: "forbidden", justification: "review test", match: ["touch x"] }] }), { mode: 0o600 }); },
  check: (r) => ({ rule_hit_exists: fs.existsSync(`${r}/rule_hit.txt`) }), answer: "allow" });
if (want("g-vblock")) await gate("verification file, mode block", { name: "write_file", args: { path: "pytest.ini", content: "[pytest]\naddopts = --co\n" } }, {
  repoFiles: { ".nexus-security.json": JSON.stringify({ verificationPaths: { mode: "block" } }), "pytest.ini": "[pytest]\n" },
  check: (r) => ({ pytest_ini: fs.readFileSync(`${r}/pytest.ini`, "utf8") }), answer: "allow" });
if (want("g-vdefault")) await gate("verification file, default mode, client answers allow_once", { name: "write_file", args: { path: "pytest.ini", content: "[pytest]\naddopts = --co\n" } }, {
  repoFiles: { "pytest.ini": "[pytest]\n" },
  check: (r) => ({ pytest_ini: fs.readFileSync(`${r}/pytest.ini`, "utf8") }), answer: "allow" });
if (want("g-del")) await gate("forbidden deletion (.git)", { name: "delete_file", args: { path: ".git" } }, { check: (r) => ({ git_dir_exists: fs.existsSync(`${r}/.git/HEAD`) }), answer: "allow" });
if (want("g-delroot")) await gate("forbidden deletion (workspace root)", { name: "delete_file", args: { path: "." } }, { check: (r) => ({ root_exists: fs.existsSync(`${r}/base.txt`) }), answer: "allow" });

// checkpoint choice: a secret in the workspace blocks the checkpoint
if (want("ckpt")) {
  const key = ["REDACTED", ""].join("\n");
  const a = await startAcp({ script: () => text("ok"), repoFiles: {} });
  fs.writeFileSync(`${a.repo}/id_rsa`, key);
  fs.writeFileSync(`${a.repo}/.env`, "AWS_SECRET_ACCESS_KEY=REDACTED;
  await a.init();
  const s = await a.newSession();
  const t0 = Date.now();
  const r = await a.call("session/prompt", prompt(s.result.sessionId, "inspect"), 60000);
  out("ckpt prompt after 60s", { reply: res(r), ms: Date.now() - t0, updates: a.msgs.filter((m) => m.method).map((m) => m.method + ":" + (m.params?.update?.sessionUpdate ?? "")), stderr_tail: a.stderr.slice(-300) });
  if (!r) {
    a.send({ jsonrpc: "2.0", method: "session/cancel", params: { sessionId: s.result.sessionId } });
    const r2 = await a.waitFor((m) => m.find((x) => x.id === 100 + 1 && !x.method) ?? m.find((x) => x.error && x.id >= 100 && x.id !== 100), 15000);
    out("ckpt after session/cancel", res(a.msgs.filter((x) => !x.method && x.id >= 101).pop()));
  }
  out("ckpt stop", await a.stop());
}

// $/cancel_request of a prompt while a permission is pending, then a second prompt
if (want("cancelreq")) {
  const a = await startAcp({ script: (n) => (n <= 2 ? writeCall(`c${n}.txt`) : text("done")) });
  await a.init();
  const s = await a.newSession();
  a.send({ jsonrpc: "2.0", id: 70, method: "session/prompt", params: prompt(s.result.sessionId, "write") });
  const p1 = await a.waitFor((m) => m.find((x) => x.method === "session/request_permission"));
  a.send({ jsonrpc: "2.0", method: "$/cancel_request", params: { requestId: 70 } });
  const r1 = await a.reply(70);
  out("cancelreq first prompt", res(r1));
  await sleep(3000);
  a.send(allow(p1.id)); // late allow for the cancelled turn
  await sleep(500);
  out("cancelreq c1 written after late allow", fs.existsSync(`${a.repo}/c1.txt`));
  // second prompt, retry while BUSY
  let r2: any;
  for (let i = 0; i < 10; i++) { r2 = await a.call("session/prompt", prompt(s.result.sessionId, "write again"), 70000); if (!r2?.error) break; await sleep(1500); }
  out("cancelreq second prompt", { reply: res(r2), permission_requests_total: a.perms().length, tools: toolUpdates(a).slice(-2), c2_written: fs.existsSync(`${a.repo}/c2.txt`) });
  out("cancelreq stop", await a.stop());
}

// same, but WITHOUT the late reply: is the second prompt's approval auto-denied?
if (want("cancelreq2")) {
  const a = await startAcp({ script: (n) => (n <= 2 ? writeCall(`c${n}.txt`) : text("done")) });
  await a.init();
  const s = await a.newSession();
  a.send({ jsonrpc: "2.0", id: 70, method: "session/prompt", params: prompt(s.result.sessionId, "write") });
  await a.waitFor((m) => m.find((x) => x.method === "session/request_permission"));
  a.send({ jsonrpc: "2.0", method: "$/cancel_request", params: { requestId: 70 } });
  out("cancelreq2 first prompt", res(await a.reply(70)));
  await sleep(3000);
  let r2: any;
  for (let i = 0; i < 10; i++) { r2 = await a.call("session/prompt", prompt(s.result.sessionId, "write again"), 70000); if (!r2?.error) break; out("cancelreq2 retry", r2.error); await sleep(1500); }
  out("cancelreq2 second prompt", { reply: res(r2), permission_requests_total: a.perms().length, tools: toolUpdates(a).slice(-2), c2_written: fs.existsSync(`${a.repo}/c2.txt`) });
  out("cancelreq2 stop", await a.stop());
}

// session/cancel while a permission is pending, then a late allow
if (want("cancel")) {
  const a = await startAcp({ script: (n) => (n === 1 ? writeCall("x1.txt") : text("done")) });
  await a.init();
  const s = await a.newSession();
  a.send({ jsonrpc: "2.0", id: 71, method: "session/prompt", params: prompt(s.result.sessionId, "write") });
  const p1 = await a.waitFor((m) => m.find((x) => x.method === "session/request_permission"));
  a.send({ jsonrpc: "2.0", method: "session/cancel", params: { sessionId: s.result.sessionId } });
  a.send(allow(p1.id));
  const r = await a.reply(71);
  a.send(allow(p1.id));
  await sleep(500);
  out("cancel", { prompt: res(r), x1_written: fs.existsSync(`${a.repo}/x1.txt`) });
  // foreign session id cancel + prompt with unknown session
  out("cancel prompt on unknown session", res(await a.call("session/prompt", prompt("session_20200101_000000_abcdefgh"))));
  out("cancel stop", await a.stop());
}

// session/load: other workspace's session, 'latest', prefix
if (want("load")) {
  const home = makeHome();
  const repoA = makeRepo();
  const a = await startAcp({ script: () => text("first answer"), home, repo: repoA });
  await a.init();
  const s = await a.newSession();
  const r = await a.call("session/prompt", prompt(s.result.sessionId, "remember the word swordfish"));
  out("load: turn in workspace A", r?.result?.stopReason ?? r?.error);
  const sid = s.result.sessionId;
  await a.stop(); // removes repoA
  fs.mkdirSync(repoA, { recursive: true }); fs.writeFileSync(`${repoA}/base.txt`, "base\n"); execSync("git init -q", { cwd: repoA, stdio: "ignore" });
  const b = await startAcp({ script: () => text("second") , home });
  await b.init();
  for (const id of ["latest", sid.slice(0, 20), "../../etc/passwd", ""]) out(`load[${JSON.stringify(id)}]`, res(await b.call("session/load", { sessionId: id, cwd: b.repo, mcpServers: [] })));
  const l = await b.call("session/load", { sessionId: sid, cwd: b.repo, mcpServers: [] });
  out("load A's session with cwd=B", { requested_cwd: b.repo, session_workspace_A: repoA, reply: res(l), replay: b.msgs.filter((m) => m.method === "session/update").map((m) => [m.params.update.sessionUpdate, short(m.params.update.content?.text ?? m.params.update.title, 60)]) });
  // where does a write land? ask for a write in the loaded session
  out("load missing id", res(await b.call("session/load", { sessionId: "session_20200101_000000_abcdefgh", cwd: b.repo, mcpServers: [] })));
  out("load stop", await b.stop());
  fs.rmSync(home, { recursive: true, force: true }); fs.rmSync(repoA, { recursive: true, force: true });
}

// request-id handling and the in-flight cap
if (want("ids")) {
  const a = await startAcp({ script: (n) => ({ kind: "text", content: "slow", delayMs: 4000 }) });
  await a.init();
  const s = await a.newSession();
  const sid = s.result.sessionId;
  // 40 prompts at once on one session: 1 runs, others refused; pending cap?
  for (let i = 0; i < 40; i++) a.send({ jsonrpc: "2.0", id: 200 + i, method: "session/prompt", params: prompt(sid, "p") });
  await sleep(1500);
  const early = a.msgs.filter((m) => m.id >= 201 && m.id < 240 && m.error);
  out("ids 39 extra prompts", { refused: early.length, messages: [...new Set(early.map((m) => m.error.message))] });
  // reuse the running prompt's id for another request
  a.send({ jsonrpc: "2.0", id: 200, method: "_nexus/receipt/get", params: { sessionId: sid } });
  await sleep(300);
  a.send({ jsonrpc: "2.0", method: "$/cancel_request", params: { requestId: 200 } });
  await sleep(1500);
  out("ids replies for id 200 after reuse + cancel_request", a.msgs.filter((m) => m.id === 200).map((m) => m.error ?? m.result?.stopReason ?? "result"));
  const fin = await a.waitFor((m) => m.filter((x) => x.id === 200).length >= 2 && m.find((x) => x.id === 200 && x.result?.stopReason), 60000);
  out("ids prompt 200 finally", res(fin));
  // odd string ids
  for (const id of ["", "a\nb", "x".repeat(256), "\u0000", "💥"]) {
    a.send({ jsonrpc: "2.0", id, method: "session/prompt", params: prompt(sid, "q") });
    const r = await a.waitFor((m) => m.find((x) => x.id === id && !x.method), 60000);
    out(`ids prompt with id ${JSON.stringify(id).slice(0, 20)}`, r ? (r.result?.stopReason ?? r.error) : "NO REPLY (session stuck?)");
  }
  out("ids bad", a.bad.length);
  out("ids stop", await a.stop());
}

// client never reads stdout
if (want("bp")) {
  const a = await startAcp({ script: () => text() });
  await a.init();
  await sleep(300);
  a.child.stdout!.pause();
  const rss0 = rssKb(a.pid);
  const line = JSON.stringify({ jsonrpc: "2.0", id: 1, method: "x".repeat(100), params: {} }) + "\n";
  const block = Buffer.from(line.repeat(2000));
  let sent = 0, stalled = false;
  const t0 = Date.now();
  while (sent < 400 * 1024 * 1024 && Date.now() - t0 < 20000) {
    if (!a.child.stdin!.write(block)) { const drained = await Promise.race([new Promise((r) => a.child.stdin!.once("drain", () => r(true))), sleep(3000).then(() => false)]); if (!drained) { stalled = true; break; } }
    sent += block.length;
  }
  out("bp", { sent_mib: Math.round(sent / 1048576), stalled_writer: stalled, rss_kb_before: rss0, rss_kb_after: rssKb(a.pid), ms: Date.now() - t0 });
  a.child.stdout!.resume();
  await sleep(1000);
  out("bp after resume: replies", a.msgs.length);
  a.child.kill("SIGKILL");
  out("bp stop", await a.stop());
}

